(()=>{const A='현미경과 세포 연구 방법',B='세포소기관의 구조와 기능',C='세포소기관의 유기적 관계',D='원핵세포와 진핵세포';
NOTE[CPN]['0-1']={pg:CPPG(1,2,18,35),b:[
 ['h','01 세포의 연구 방법'],
 ['p','세포는 생물체의 ==구조적 단위==이자 생명활동을 수행하는 ==기능적 단위==\n세포의 구조 연구는 ==현미경 발명 이후==에 이루어졌고, 세포소기관의 기능 연구는 ==세포분획법, 자기방사법== 등으로 가능해짐'],
 ['vs',['광학 현미경','==가시광선==을 ==대물렌즈와 접안렌즈==로 굴절시켜 상을 확대\n==살아 있는 세포==의 모양·크기, 핵·마이토콘드리아·엽록체 등 일부 세포소기관 관찰 (염색하면 더 잘 구별)\n종류: 일반 광학 현미경, ==위상차 현미경==, ==형광 현미경=='],['전자 현미경','가시광선보다 ==파장이 짧은 전자선==을 굴절시켜 상을 확대\n광학 현미경보다 ==배율과 해상력이 높음== → 세포소기관의 ==미세 구조== 관찰\n==SEM(주사)==: 시료 ==표면의 입체 영상== → 세포 표면·외부 형태\n==TEM(투과)==: 시료 ==얇은 단면==을 투과 → 세포 ==내부 미세 구조==']],
 ['def','해상력','매우 가까이 있는 두 점을 ==구별할 수 있는 최소한의 거리==로 나타내는 능력'],
 ['h','마이크로미터로 세포 크기 측정'],
 ['p','대물마이크로미터: 1 mm를 100등분 → ==눈금 한 칸 = 10 µm== (재물대에 올림)\n접안마이크로미터: 접안렌즈 안에 끼움. 눈금 한 칸의 길이는 ==배율에 따라 달라짐==\n==접안 한 칸의 길이 = (대물 눈금 칸 수 ÷ 접안 눈금 칸 수) × 10 µm==\n배율을 ==100배 → 400배==로 높이면 접안마이크로미터 눈금 한 칸의 길이는 ==1/4로 짧아짐==\n세포 크기 = 세포가 차지하는 접안 눈금 칸 수 × 접안 한 칸의 길이'],
 ['h','세포분획법'],
 ['p','세포를 ==균질기==로 부순 뒤(세포 파쇄액) ==원심분리기==로 세포소기관을 ==크기와 밀도==에 따라 단계적으로 분리\n==느린 회전 속도==에서는 크고 무거운 것이 먼저 침전, 속도가 빨라질수록 작은 것이 침전'],
 ['flow',['동물 세포: 1000 g ==핵==','20000 g ==마이토콘드리아==','80000 g ==소포체==','150000 g ==라이보솜==']],
 ['p','세포벽을 제거한 식물 세포: ==핵 → 엽록체 → 마이토콘드리아 → 소포체 → 라이보솜== 순으로 분리\n(g = 중력 가속도의 배수, 1000 g = 중력 가속도의 1000배)'],
 ['h','자기방사법'],
 ['p','==방사성 동위원소==(3H, 14C, 32P, 35S 등)로 ==표지한 화합물==을 세포에 공급 → 방출되는 ==방사선을 추적==\n예: ==14C·35S로 표지한 아미노산==을 공급하고 시간에 따라 방사선을 내는 세포소기관을 조사 → ==단백질 합성·이동 경로== 확인\n광합성, 세포호흡, 세포분열, 유전 연구에도 이용 / 요즘은 위험성 때문에 ==형광 물질==로 대체하기도'],
 ['key','자기방사법 그래프 읽기','공급 직후 방사선 양이 먼저 높아지는 곳 → 나중에 높아지는 곳 순서가 ==물질의 이동 순서==\n단백질 분비: ==거친면소포체 → 골지체 → 분비 소낭=='],
 ['h','02 세포소기관의 구조와 기능'],
 ['p','세포는 ==세포막==으로 둘러싸여 있고 세포막은 세포 안팎의 ==물질 출입을 조절==\n진핵세포: 핵 + 세포질(막 있는 소기관 + ==막 없는 소기관: 라이보솜, 중심체==)'],
 ['tbl',['세포소기관','막 구조','구조·기능'],[
  ['핵','==이중막(핵막)==','핵막에 ==핵공==(물질 이동 통로), 속에 ==DNA(염색질)와 인==(rRNA 합성). 세포의 구조·기능 결정, 생명활동 조절'],
  ['라이보솜','==막 없음==','rRNA + 단백질, 크기가 다른 ==2개의 단위체==. 유전정보에 따라 ==단백질 합성== (거친면소포체에 붙어 있거나 세포질에 흩어져 있음)'],
  ['소포체','==단일막==','==거친면==(라이보솜 부착): 단백질 가공·운반 / ==매끈면==: 인지질·스테로이드 합성, 해독, ==Ca²⁺ 저장=='],
  ['골지체','==단일막==','납작한 주머니 ==시스터나==. 소포체에서 온 단백질·지질을 ==가공 → 수송·분비=='],
  ['라이소솜','==단일막==','골지체에서 떨어져 생성. ==가수분해효소==로 ==세포내소화==, 손상된 소기관·노폐물 분해'],
  ['마이토콘드리아','==이중막==','내막이 안쪽으로 돌출한 ==크리스타==, 안쪽 공간 ==바탕질==. ==세포호흡== → 유기물의 화학 에너지가 ==ATP== 에너지로 전환. 자체 ==DNA·라이보솜==으로 스스로 복제'],
  ['엽록체','==이중막==','내막 안쪽에 ==타이라코이드==가 쌓인 ==그라나==, 안쪽 공간 ==스트로마==. ==광합성== → 빛에너지를 화학 에너지로 전환. 자체 DNA·라이보솜 있음'],
  ['액포','==단일막==','수분량·삼투압 조절, 식물 세포 형태 유지, 유기물·노폐물·수용성 색소 저장 (성숙한 식물 세포에서 크게 발달)'],
  ['세포벽','—','식물 세포의 세포막 바깥, 주성분 ==셀룰로스==, 세포 보호·형태 유지 (1차 세포벽, 성숙하면 2차 세포벽)'],
  ['중심체','막 없음','==중심립 2개==(직각 배열, 미세소관 다발) → ==방추사 형성==, 동물 세포에 있음'],
  ['세포골격','—','단백질 섬유 그물. 세포 형태 결정, 소기관 고정·이동']]],
 ['tbl',['세포골격','굵기','기능'],[['미세소관','가장 ==굵음==','중심체, 방추사, 섬모, 편모 구성'],['중간섬유','중간','세포소기관 고정, 세포 형태 유지'],['미세섬유','가장 ==가늘음==','세포막 지탱, 세포질 분열']]],
 ['vs',['동물 세포에만 있음','==중심체=='],['식물 세포에만 있음','==엽록체, 세포벽==, 크게 발달한 ==액포==']],
 ['key','핵 / 마이토콘드리아 / 엽록체 공통점','==이중막==. 마이토콘드리아·엽록체는 ==자체 DNA와 라이보솜==이 있어 스스로 복제·증식, ==에너지전환== 일어남\n막 구조: ==이중막== = 핵·마이토콘드리아·엽록체 / ==단일막== = 소포체·골지체·라이소솜·액포 / ==막 없음== = 라이보솜·중심체'],
 ['h','세포소기관의 유기적 관계 (단백질 분비)'],
 ['flow',['==핵== DNA의 유전정보로 단백질 합성 지시','==거친면소포체==의 라이보솜에서 합성 → 소포체에서 가공 → ==운반 소낭==','==골지체==에서 가공 → 운반 소낭','==세포막==과 소낭 막이 융합 → 세포 밖으로 ==분비==']],
 ['p','골지체의 일부가 떨어져 ==라이소솜== 생성 → 세포 안으로 들어온 이물질을 가수분해효소로 분해'],
 ['h','03 원핵세포와 진핵세포'],
 ['p','모든 세포의 기본 구조: ==세포막, 유전물질, 라이보솜==\n구분 기준: 세포 내 ==막 구조==(핵막, 막성 세포소기관)의 유무'],
 ['tbl',['구분','원핵세포 (예: 세균)','진핵세포 (동물·식물·원생생물·균류)'],[['핵막','==없음== (유전물질이 세포질에 퍼져 있음)','==있음== (유전물질이 핵 속)'],['막성 세포소기관','==없음==','==있음== (마이토콘드리아, 소포체, 골지체 등)'],['DNA','하나의 ==원형 DNA== (일부는 ==플라스미드==도 가짐)','여러 개의 ==선형 DNA==, ==히스톤 단백질==과 결합해 염색질'],['라이보솜','있음 (진핵세포보다 ==작음==)','있음'],['세포벽','대부분 ==펩티도글리칸== 포함','식물: ==셀룰로스==']]],
 ['tip','**소기관 막 개수**(이중막: 핵·마이토콘드리아·엽록체 / 단일막: 소포체·골지체·라이소솜·액포 / 막 없음: 라이보솜·중심체)와 **분리 순서**(핵→(엽록체)→마이토콘드리아→소포체→라이보솜)가 단골! 마이크로미터는 **배율 ×4 → 한 칸 길이 1/4**. 단백질 분비 = **핵 → 거친면소포체 → 골지체 → 세포막**.']]};
CPQ['0-1']=[
 {t:'sh',g:A,q:'시료 표면의 입체 영상을 얻어 세포의 표면이나 외부 형태를 연구하는 데 쓰는 현미경은 [빈칸] 전자 현미경이다.',a:['주사','sem'],m:'주사(SEM)',e:'투과 전자 현미경(TEM)은 시료의 얇은 단면을 투과해 세포 내부의 미세 구조를 연구해요.'},
 {t:'ox',g:A,q:'광학 현미경으로는 살아 있는 세포를 관찰할 수 있다.',a:true,e:'광학 현미경은 가시광선을 이용하므로 살아 있는 세포의 모양과 크기, 일부 세포소기관을 관찰할 수 있어요.'},
 {t:'mc',g:A,q:'세포분획법에서 느린 회전 속도로 가장 먼저 침전되는 세포소기관은?',o:['라이보솜','소포체','마이토콘드리아','핵','골지체'],a:3,e:'크고 무거운 핵이 가장 먼저 침전되고, 속도가 빨라질수록 작은 소기관이 침전돼요.'},
 {t:'sh',g:A,q:'방사성 동위원소로 표지한 화합물을 공급하고 방출되는 방사선을 추적하여 물질의 이동과 변화를 알아보는 방법을 [빈칸]법이라고 한다.',a:['자기방사'],m:'자기방사',e:'14C나 35S로 표지한 아미노산을 이용하면 단백질의 이동 경로를 알 수 있어요.'},
 {t:'mc',g:B,q:'막으로 둘러싸여 있지 않은 세포소기관은?',o:['소포체','골지체','라이소솜','마이토콘드리아','라이보솜'],a:4,e:'라이보솜과 중심체는 막이 없는 세포소기관이에요.'},
 {t:'sh',g:B,q:'가수분해효소가 들어 있어 세포내소화를 담당하는 세포소기관은 [빈칸]이다.',a:['라이소솜'],m:'라이소솜',e:'라이소솜은 골지체의 일부가 떨어져 나와 만들어져요.'},
 {t:'ox',g:B,q:'마이토콘드리아와 엽록체는 자체 DNA와 라이보솜이 있어 스스로 복제하여 증식할 수 있다.',a:true,e:'두 소기관의 공통점이에요. 또한 둘 다 이중막이고 에너지전환이 일어나요.'},
 {t:'mc',g:B,q:'인에서 합성되는 물질은?',o:['단백질','rRNA','글리코젠','ATP','히스톤'],a:1,e:'핵 속의 인에서 rRNA가 합성되고, 라이보솜 단위체를 구성해요.'},
 {t:'ox',g:D,q:'원핵세포에는 핵막이 없고 막으로 둘러싸인 세포소기관도 없다.',a:true,e:'원핵세포와 진핵세포는 세포 내 막 구조의 유무로 구분해요.'},
 {t:'mc',g:D,q:'원핵세포에 대한 설명으로 옳은 것은?',o:['여러 개의 선형 DNA가 있다.','핵막으로 둘러싸인 핵이 있다.','라이보솜이 없다.','마이토콘드리아가 있다.','하나의 원형 DNA를 가진다.'],a:4,e:'원핵세포는 하나의 원형 DNA를 가지며 라이보솜은 있지만 핵막과 막성 소기관은 없어요.'},
 {lv:'x',t:'mc',g:A,q:'현미경에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. 전자 현미경은 가시광선보다 파장이 짧은 전자선을 이용한다.\nㄴ. 전자 현미경은 광학 현미경보다 해상력이 높다.\nㄷ. 투과 전자 현미경은 시료의 표면을 입체적으로 관찰하는 데 적합하다.',o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:1,e:'시료 표면의 입체 관찰에는 주사 전자 현미경(SEM)이 적합하고, 투과 전자 현미경(TEM)은 내부 단면 관찰용이에요.'},
 {lv:'x',t:'mc',g:A,q:'배율 100배에서 접안마이크로미터 눈금 20칸이 대물마이크로미터 눈금 8칸과 일치하였다. 대물마이크로미터 눈금 한 칸의 길이는 10 µm이다. 접안마이크로미터 눈금 한 칸의 길이는?',o:['2 µm','4 µm','5 µm','8 µm','20 µm'],a:1,e:'접안 한 칸 = (8 ÷ 20) × 10 µm = 4 µm예요.'},
 {lv:'x',t:'mc',g:A,q:'배율 100배에서 접안마이크로미터 눈금 한 칸의 길이가 4 µm였다. 배율을 400배로 바꿨을 때, 접안마이크로미터 눈금 한 칸의 길이와 접안 눈금 15칸을 차지하던 세포(60 µm)가 차지하는 접안 눈금 칸 수를 옳게 짝지은 것은?',o:['1 µm, 15칸','1 µm, 60칸','4 µm, 15칸','16 µm, 15칸','16 µm, 60칸'],a:1,e:'배율이 4배가 되면 한 칸의 길이는 1/4이 되어 1 µm이고, 세포는 60칸을 차지해요.'},
 {lv:'x',t:'mc',g:A,q:'동물 세포를 균질기로 부순 파쇄액을 원심분리할 때 침전되는 세포소기관이 옳게 짝지어진 것은? (회전 속도는 ㉠<㉡<㉢<㉣ 순으로 빠르다.)\n\n[표]',tb:{h:['단계','회전 속도','침전 소기관'],r:[['1','㉠','(가)'],['2','㉡','(나)'],['3','㉢','(다)'],['4','㉣','(라)']]},o:['핵, 마이토콘드리아, 소포체, 라이보솜','마이토콘드리아, 핵, 소포체, 라이보솜','핵, 소포체, 마이토콘드리아, 라이보솜','라이보솜, 소포체, 마이토콘드리아, 핵','핵, 마이토콘드리아, 라이보솜, 소포체'],a:0,e:'동물 세포는 핵 → 마이토콘드리아 → 소포체 → 라이보솜 순으로 분리돼요.'},
 {lv:'x',t:'mc',g:B,q:'다음은 세포소기관 (가)~(다)의 특징이다.\n\n(가) 이중막으로 둘러싸여 있고 내막이 돌출한 크리스타가 있다.\n(나) 단일막으로 둘러싸인 납작한 주머니(시스터나)가 쌓여 있다.\n(다) 단일막이며 가수분해효소가 들어 있다.\n\n(가)~(다)를 옳게 짝지은 것은?',o:['마이토콘드리아, 골지체, 라이소솜','엽록체, 골지체, 소포체','마이토콘드리아, 소포체, 라이소솜','핵, 골지체, 액포','엽록체, 소포체, 라이소솜'],a:0,e:'크리스타는 마이토콘드리아에 있고, 시스터나는 골지체의 구조이며, 가수분해효소는 라이소솜에 있어요.'},
 {lv:'x',t:'mc',g:B,q:'소포체에 대한 설명으로 옳지 않은 것은?',o:['단일막 구조이다.','거친면소포체에는 라이보솜이 붙어 있다.','매끈면소포체는 인지질과 스테로이드를 합성한다.','매끈면소포체는 독성 물질의 해독에 관여한다.','거친면소포체에서 합성된 단백질은 곧바로 세포막으로 분비된다.'],a:4,e:'소포체에서 가공된 단백질은 운반 소낭으로 골지체에 전달되고, 골지체를 거쳐 분비돼요.'},
 {lv:'x',t:'mc',g:C,q:'다음은 어떤 세포에 방사성 동위원소로 표지한 아미노산을 짧게 공급한 후 시간에 따라 세포소기관 (가)~(다)에서 검출된 방사선 양을 나타낸 것이다.\n\n[표]\n\n(가)~(다)를 옳게 짝지은 것은? ((가)~(다)는 골지체, 거친면소포체, 분비 소낭 중 하나이다.)',tb:{h:['시간(분)','(가)','(나)','(다)'],r:[['5','많음','없음','없음'],['20','적음','많음','없음'],['60','없음','적음','많음']]},o:['거친면소포체, 골지체, 분비 소낭','골지체, 거친면소포체, 분비 소낭','분비 소낭, 골지체, 거친면소포체','거친면소포체, 분비 소낭, 골지체','골지체, 분비 소낭, 거친면소포체'],a:0,e:'단백질은 거친면소포체 → 골지체 → 분비 소낭 순으로 이동하므로 방사선이 이 순서로 나타나요.'},
 {lv:'x',t:'mc',g:C,q:'분비 단백질이 합성되어 세포 밖으로 분비되는 과정을 순서대로 옳게 나열한 것은?',o:['핵 → 골지체 → 거친면소포체 → 세포막','거친면소포체 → 핵 → 골지체 → 세포막','핵 → 거친면소포체 → 골지체 → 세포막','골지체 → 거친면소포체 → 라이소솜 → 세포막','핵 → 라이소솜 → 골지체 → 세포막'],a:2,e:'핵의 유전정보 → 거친면소포체에서 합성·가공 → 골지체에서 가공 → 분비 소낭이 세포막과 융합하여 분비돼요.'},
 {lv:'x',t:'mc',g:D,q:'표는 세포 (가)~(다)에서 특징 ㉠~㉢의 유무를 나타낸 것이다. (가)~(다)는 세균, 동물 세포, 식물 세포를 순서 없이 나타낸 것이고, ㉠~㉢은 핵막, 세포벽, 엽록체를 순서 없이 나타낸 것이다. ○는 있음, ×는 없음이다.\n\n[표]\n\n(가)~(다)를 옳게 짝지은 것은?',tb:{h:['구분','㉠','㉡','㉢'],r:[['(가)','○','○','○'],['(나)','○','×','×'],['(다)','×','○','×']]},o:['식물 세포, 동물 세포, 세균','식물 세포, 세균, 동물 세포','세균, 식물 세포, 동물 세포','동물 세포, 식물 세포, 세균','동물 세포, 세균, 식물 세포'],a:1,e:'세 가지를 모두 가진 (가)는 식물 세포예요. 세균은 핵막과 엽록체가 없고 세포벽만 있으므로 ㉠이 세포벽이고 (나)가 세균이에요. ㉡은 핵막, ㉢은 엽록체이므로 (다)가 동물 세포예요.'},
 {lv:'x',t:'mc',g:D,q:'원핵세포와 진핵세포에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. 세균은 원핵세포로 이루어져 있다.\nㄴ. 진핵세포의 DNA는 히스톤 단백질과 결합해 염색질을 이룬다.\nㄷ. 원핵세포의 라이보솜은 진핵세포의 라이보솜보다 크기가 크다.',o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:1,e:'원핵세포의 라이보솜은 진핵세포의 라이보솜보다 작아요.'}
];
CPMK['0-1']=[
 {g:A,q:'표는 현미경 (가)~(다)의 특징을 나타낸 것이다.\n\n[표]\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. (가)는 광학 현미경이다.\nㄴ. (나)는 세포 내부의 미세 구조를 연구하는 데 적합하다.\nㄷ. (다)는 시료를 투과한 전자선으로 상을 얻는다.',tb:{h:['현미경','이용하는 것','특징'],r:[['(가)','가시광선','살아 있는 세포를 관찰할 수 있음'],['(나)','전자선','시료의 얇은 단면을 투과'],['(다)','전자선','시료 표면에서 반사되어 나온 전자로 입체 영상을 얻음']]},o:['ㄱ','ㄷ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ'],a:2,e:'(가) 광학 현미경, (나) 투과 전자 현미경, (다) 주사 전자 현미경이에요. (다)는 시료 표면에서 반사되어 나온 전자를 이용해요.'},
 {g:A,q:'배율 200배에서 대물마이크로미터 눈금 10칸과 접안마이크로미터 눈금 25칸이 일치하였다. 대물마이크로미터 눈금 한 칸의 길이는 10 µm이다. 이 배율에서 접안마이크로미터 눈금 12칸을 차지하는 세포의 길이는?',o:['12 µm','24 µm','36 µm','48 µm','60 µm'],a:3,e:'접안 한 칸 = (10 ÷ 25) × 10 µm = 4 µm이고, 12칸이면 48 µm예요.'},
 {g:A,q:'표는 동물 세포를 균질기로 부수어 원심분리하였을 때 얻은 침전물 (가)~(다)의 특징이다.\n\n[표]\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. (가)는 핵이다.\nㄴ. (나)에서는 세포호흡이 일어난다.\nㄷ. (다)는 (가)와 (나)보다 빠른 회전 속도에서 침전된다.',tb:{h:['침전물','특징'],r:[['(가)','가장 먼저 침전되며 DNA와 인이 들어 있음'],['(나)','이중막으로 둘러싸여 있고 내막이 안쪽으로 돌출한 구조가 있음'],['(다)','막으로 둘러싸여 있지 않고 rRNA와 단백질로 이루어짐']]},o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:4,e:'(가) 핵, (나) 마이토콘드리아, (다) 라이보솜이에요. 작은 소기관일수록 빠른 속도에서 침전돼요.'},
 {g:A,q:'다음은 세포 연구 방법 (가)~(다)에 대한 설명이다.\n\n(가) 방사성 동위원소로 표지한 아미노산을 세포에 공급하고 방출되는 방사선을 추적한다.\n(나) 세포를 균질기로 부순 뒤 원심분리하여 세포소기관을 분리한다.\n(다) 전자선을 이용하여 세포소기관의 미세 구조를 관찰한다.\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. (가)로 단백질의 이동 경로를 알 수 있다.\nㄴ. (나)는 세포소기관의 크기와 밀도 차이를 이용한다.\nㄷ. (다)는 세포분획법이다.',o:['ㄱ','ㄴ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ'],a:2,e:'(가)는 자기방사법, (나)는 세포분획법, (다)는 전자 현미경 관찰이에요.'},
 {g:B,q:'표는 세포소기관 (가)~(다)의 특징을 나타낸 것이다. (가)~(다)는 마이토콘드리아, 엽록체, 골지체를 순서 없이 나타낸 것이다. ○는 있음, ×는 없음이다.\n\n[표]\n\n(가)~(다)를 옳게 짝지은 것은?',tb:{h:['특징','(가)','(나)','(다)'],r:[['이중막으로 둘러싸여 있다.','○','○','×'],['빛에너지를 화학 에너지로 전환한다.','○','×','×'],['자체 DNA가 있다.','○','○','×']]},o:['마이토콘드리아, 엽록체, 골지체','엽록체, 마이토콘드리아, 골지체','엽록체, 골지체, 마이토콘드리아','골지체, 엽록체, 마이토콘드리아','마이토콘드리아, 골지체, 엽록체'],a:1,e:'빛에너지를 전환하는 (가)는 엽록체이고, 이중막과 자체 DNA를 가진 (나)는 마이토콘드리아, 둘 다 없는 (다)는 단일막인 골지체예요.'},
 {g:B,q:'표는 두 종류의 세포 A, B에서 세포 구조 ㉠~㉢의 유무를 나타낸 것이다. A와 B는 각각 동물 세포와 식물 세포 중 하나이고, ㉠~㉢은 엽록체, 중심체, 라이보솜을 순서 없이 나타낸 것이다. ○는 있음, ×는 없음이다.\n\n[표]\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. A는 식물 세포이다.\nㄴ. ㉡은 방추사 형성에 관여한다.\nㄷ. ㉢은 단일막으로 둘러싸여 있다.',tb:{h:['구분','㉠','㉡','㉢'],r:[['A','○','×','○'],['B','×','○','○']]},o:['ㄱ','ㄴ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ'],a:2,e:'㉢은 두 세포에 모두 있는 라이보솜이고 막이 없어요. ㉠은 엽록체(식물 세포 A에만), ㉡은 중심체(동물 세포 B에만)예요.'},
 {g:B,q:'다음은 세포소기관에 대한 학생들의 대화이다.\n\n갑: 거친면소포체는 단백질을 가공하고 운반하는 일을 해.\n을: 골지체는 이중막으로 둘러싸여 있어.\n병: 매끈면소포체는 독성 물질을 해독하는 데 관여해.\n\n옳게 말한 학생만을 고른 것은?',o:['갑','을','병','갑, 병','을, 병'],a:3,e:'골지체는 단일막 구조예요.'},
 {g:B,q:'표는 마이토콘드리아와 엽록체의 구조 (가)~(라)의 특징을 나타낸 것이다.\n\n[표]\n\n(가)~(라)를 옳게 짝지은 것은?',tb:{h:['구조','특징'],r:[['(가)','마이토콘드리아 내막이 안쪽으로 돌출한 주름'],['(나)','마이토콘드리아 내막 안쪽 공간으로 세포호흡 효소가 있음'],['(다)','엽록체에서 타이라코이드가 쌓여 층을 이룬 구조'],['(라)','엽록체 내막 안쪽 공간으로 포도당 합성 효소가 있음']]},o:['크리스타, 그라나, 바탕질, 스트로마','바탕질, 크리스타, 그라나, 스트로마','크리스타, 바탕질, 그라나, 스트로마','크리스타, 바탕질, 스트로마, 그라나','그라나, 바탕질, 크리스타, 스트로마'],a:2,e:'(가) 크리스타, (나) 바탕질, (다) 그라나, (라) 스트로마예요.'},
 {g:B,q:'다음은 라이소솜에 대한 실험이다.\n\n[실험 과정 및 결과]\n• 세포에 세균을 넣었더니 세포막이 세균을 둘러싸 식포가 형성되었다.\n• 식포에 라이소솜이 융합하자 식포 속의 세균이 분해되었다.\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. 라이소솜은 골지체의 일부가 떨어져 나와 만들어진다.\nㄴ. 세균의 분해에는 가수분해효소가 관여한다.\nㄷ. 라이소솜은 이중막으로 둘러싸여 있다.',o:['ㄱ','ㄴ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ'],a:2,e:'라이소솜은 단일막으로 둘러싸여 있어요.'},
 {g:B,q:'표는 사람의 세포 (가)~(다)에서 상대적으로 잘 발달한 세포소기관 ㉠~㉢을 나타낸 것이다. ㉠~㉢은 마이토콘드리아, 거친면소포체, 매끈면소포체를 순서 없이 나타낸 것이다.\n\n[표]\n\n㉠~㉢을 옳게 짝지은 것은?',tb:{h:['세포','특징','발달한 소기관'],r:[['(가)','스테로이드호르몬을 합성하는 부신겉질 세포','㉠'],['(나)','분비 작용이 활발한 이자세포','㉡'],['(다)','에너지를 많이 사용하는 근육세포','㉢']]},o:['마이토콘드리아, 거친면소포체, 매끈면소포체','거친면소포체, 매끈면소포체, 마이토콘드리아','매끈면소포체, 마이토콘드리아, 거친면소포체','매끈면소포체, 거친면소포체, 마이토콘드리아','거친면소포체, 마이토콘드리아, 매끈면소포체'],a:3,e:'스테로이드 합성은 매끈면소포체, 분비 단백질 가공은 거친면소포체, 에너지 생성은 마이토콘드리아와 관련돼요.'},
 {g:C,q:'다음은 분비 단백질이 합성되어 분비되는 과정에 관여하는 세포소기관 (가)~(라)의 특징이다.\n\n(가) 막이 없으며 단백질을 합성한다.\n(나) 합성된 단백질을 가공하여 운반 소낭을 만든다.\n(다) 소낭으로 전달된 단백질을 가공하여 세포막 쪽으로 운반 소낭을 만든다.\n(라) 소낭의 막과 융합하여 단백질이 세포 밖으로 분비된다.\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. (가)는 라이보솜이다.\nㄴ. (나)와 (다)는 모두 단일막 구조이다.\nㄷ. (라)는 세포막이다.',o:['ㄱ','ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:4,e:'(가) 라이보솜, (나) 소포체, (다) 골지체, (라) 세포막이에요. 소포체와 골지체는 단일막이에요.'},
 {g:C,q:'다음은 핵에 대한 학생들의 대화이다.\n\n갑: 핵 속의 DNA 유전정보에 따라 단백질의 특성이 결정돼.\n을: 라이보솜 단위체는 세포질에서만 만들어져.\n병: 핵막의 핵공을 통해 핵과 세포질 사이에 물질이 이동해.\n\n옳게 말한 학생만을 고른 것은?',o:['갑','병','갑, 병','을, 병','갑, 을, 병'],a:2,e:'인에서 합성된 rRNA가 핵공을 통해 들어온 라이보솜 단백질과 함께 라이보솜 단위체를 구성해요.'},
 {g:C,q:'어떤 약물이 골지체의 기능을 억제하였다. 이 약물을 처리한 분비 세포에서 나타날 현상으로 가장 적절한 것은?',o:['라이보솜에서 단백질이 합성되지 않는다.','소포체에서 골지체로 전달되어야 할 단백질이 소포체에 쌓이고 분비가 줄어든다.','핵에서 DNA가 합성되지 않는다.','마이토콘드리아에서 세포호흡이 즉시 멈춘다.','엽록체에서 광합성이 증가한다.'],a:1,e:'골지체가 단백질을 가공·수송하지 못하면 앞 단계인 소포체에 단백질이 쌓이고 세포 밖 분비가 감소해요.'},
 {g:D,q:'표는 세포 (가)와 (나)의 특징 ㉠~㉢의 유무를 나타낸 것이다. (가)와 (나)는 대장균과 효모(진핵세포)를 순서 없이 나타낸 것이고, ㉠~㉢은 핵막, 라이보솜, 막으로 둘러싸인 세포소기관을 순서 없이 나타낸 것이다. ○는 있음, ×는 없음이다.\n\n[표]\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. (가)는 대장균이다.\nㄴ. ㉡은 라이보솜이다.\nㄷ. ㉢은 (나)의 유전물질이 세포질에 퍼져 있게 한다.',tb:{h:['구분','㉠','㉡','㉢'],r:[['(가)','×','○','×'],['(나)','○','○','○']]},o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:1,e:'(가)는 원핵세포인 대장균이고 ㉡은 두 세포에 모두 있는 라이보솜이에요. ㉢은 핵막 또는 막성 소기관이고, (나)는 핵막이 있어 유전물질이 핵 속에 있어요.'},
 {g:D,q:'표는 세포 (가)와 (나)의 특징을 나타낸 것이다. (가)와 (나)는 대장균과 시금치 잎의 세포를 순서 없이 나타낸 것이다.\n\n[표]\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. (가)는 대장균이다.\nㄴ. (나)의 세포벽 주성분은 셀룰로스이다.\nㄷ. (나)의 DNA는 히스톤 단백질과 결합해 있다.',tb:{h:['특징','(가)','(나)'],r:[['DNA의 모양','원형 하나','여러 개의 선형'],['세포벽','펩티도글리칸 포함','있음'],['엽록체','없음','있음']]},o:['ㄱ','ㄴ','ㄷ','ㄱ, ㄴ','ㄱ, ㄴ, ㄷ'],a:4,e:'(가)는 원핵세포인 대장균, (나)는 진핵세포인 식물 세포예요. 진핵세포의 DNA는 히스톤과 결합해 염색질을 이루어요.'},
 {g:D,q:'다음은 어떤 세포 X의 특징이다.\n\n• 핵막이 없고 DNA가 세포질에 퍼져 있다.\n• 세포벽에 펩티도글리칸이 포함되어 있다.\n• 플라스미드라는 작은 원형 DNA를 가진다.\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. X는 원핵세포이다.\nㄴ. X에는 마이토콘드리아가 있다.\nㄷ. X의 라이보솜은 진핵세포의 라이보솜보다 작다.',o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:2,e:'원핵세포에는 막성 세포소기관인 마이토콘드리아가 없어요.'},
 {g:B,q:'다음 중 이중막으로 둘러싸인 세포소기관만을 있는 대로 고른 것은?\n\nㄱ. 골지체\nㄴ. 엽록체\nㄷ. 핵\nㄹ. 액포\nㅁ. 마이토콘드리아',o:['ㄴ, ㄷ','ㄴ, ㅁ','ㄴ, ㄷ, ㅁ','ㄱ, ㄷ, ㅁ','ㄷ, ㄹ, ㅁ'],a:2,e:'핵, 엽록체, 마이토콘드리아는 이중막이에요. 골지체와 액포는 단일막이에요.'},
 {g:B,q:'액포에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. 단일막으로 둘러싸여 있다.\nㄴ. 노폐물과 수용성 색소를 저장한다.\nㄷ. 빛에너지를 이용해 포도당을 합성한다.',o:['ㄱ','ㄴ','ㄷ','ㄱ, ㄴ','ㄴ, ㄷ'],a:3,e:'광합성은 엽록체에서 일어나요. 액포는 성숙한 식물 세포에서 크게 발달해 수분량과 삼투압을 조절해요.'},
 {g:D,q:'다음은 세포의 구조에 대한 학생들의 대화이다.\n\n갑: 모든 세포는 세포막, 유전물질, 라이보솜을 가지고 있어.\n을: 원핵세포는 핵막이 없어서 DNA가 세포질에 퍼져 있어.\n병: 진핵세포의 DNA는 모두 원형이야.\n\n옳게 말한 학생만을 고른 것은?',o:['갑','을','갑, 을','갑, 병','을, 병'],a:2,e:'진핵세포는 여러 개의 선형 DNA를 가지고, 원핵세포가 원형 DNA를 가져요.'}
];
Object.assign(TIPS,{[A]:'광학(가시광선, 살아 있는 세포) vs 전자(전자선, 해상력↑; SEM 표면 / TEM 단면). 접안 한 칸 = (대물 칸 수 ÷ 접안 칸 수) × 10 µm, 배율 ×4 → 한 칸 길이 1/4. 분획 순서 핵 → (엽록체) → 마이토콘드리아 → 소포체 → 라이보솜!',[B]:'이중막: 핵·마이토콘드리아·엽록체 / 단일막: 소포체·골지체·라이소솜·액포 / 막 없음: 라이보솜·중심체. 기능을 소기관마다 한 줄로 외우세요!',[C]:'단백질 분비: 핵(DNA) → 거친면소포체(합성·가공) → 골지체(가공) → 분비 소낭 → 세포막. 자기방사법에서 방사선이 먼저 나타나는 곳이 앞 단계!',[D]:'구분 기준 = 막 구조(핵막·막성 소기관) 유무. 원핵: 원형 DNA, 작은 라이보솜, 펩티도글리칸 세포벽 / 진핵: 선형 DNA + 히스톤, 식물은 셀룰로스 세포벽.'});
})();
// ----- 03 세포막을 통한 물질 이동 (교과서 36~44쪽) -----
(()=>{const A='세포막의 구조와 특성',B='확산과 삼투',C='삼투 현상과 식물 세포',D='능동수송과 소낭 수송';
NOTE[CPN]['0-2']={pg:CPPG(1,3,36,44),b:[
 ['h','01 세포막의 구조'],
 ['p','세포막: 세포의 형태 유지, 세포 밖 신호를 안으로 전달, ==물질 이동 조절==\n주성분 = ==인지질과 단백질==\n전자 현미경으로 보면 ==진한 선이 두 겹== → ==인지질 이중층== 때문'],
 ['ul',['인지질: ==머리(인산, 친수성)== / ==꼬리(지방산, 소수성)==','세포 안팎은 수용성 환경 → ==친수성 머리는 양쪽 바깥(물과 접함)==, ==소수성 꼬리는 서로 마주 봄==','막단백질: 인지질 이중층에 ==파묻히거나, 관통하거나, 표면에 붙어== 있음']],
 ['key','유동모자이크막','인지질과 막단백질이 고정되지 않고 ==수평으로 자유롭게 이동(유동성)== + 막단백질이 곳곳에 ==박혀 있는(모자이크)== 구조\n(사람 세포 + 쥐 세포 융합 실험: 형광 물질이 시간이 지나며 ==섞임== → 막단백질의 유동성 증거)\n인지질은 막의 ==기본 구조==, 막단백질은 막의 ==기능== 결정'],
 ['tbl',['막단백질','기능'],[['수송단백질','막을 통한 ==물질 이동==에 관여'],['수용체단백질','세포 밖의 특정 화학 물질을 인식 → ==신호 전달=='],['효소단백질','==물질대사==에 관여'],['탄수화물이 붙은 단백질','==세포 인식==']]],
 ['h','02 세포막을 통한 물질 이동'],
 ['def','선택적 투과성','물질의 종류에 따라 이동이 선택적으로 일어나는 세포막의 특성\n크기가 작고 ==극성이 없는== 물질(O₂, CO₂)은 인지질 이중층을 쉽게 통과, ==대부분의 물질은 막단백질의 도움==이 필요'],
 ['p','에너지 사용 X: ==확산, 삼투(촉진확산 포함)== / 에너지 사용 O: ==능동수송, 세포내섭취, 세포외배출=='],
 ['h','확산'],
 ['p','==농도가 높은 쪽 → 낮은 쪽==(농도 기울기 방향), 세포의 ==에너지 사용 없음=='],
 ['tbl',['구분','경로','예'],[['단순확산','물질이 ==인지질 이중층을 직접 통과==','폐포-모세혈관, 모세혈관-조직 세포 사이 ==O₂, CO₂== 이동'],['촉진확산','물질이 ==수송단백질==(통로단백질·운반체단백질)을 통해 이동','뉴런의 ==Na⁺ 통로==를 통한 Na⁺ 이동, 혈액의 ==포도당==이 운반체단백질로 이동']]],
 ['ul',['==통로단백질==: 이온 같은 물질이 지나는 통로','==운반체단백질==: 단백질의 ==구조 변화==로 물질 운반','촉진확산은 단순확산보다 ==이동 속도가 빠르지만==, 농도 차가 커져도 모든 수송단백질이 사용되면 ==속도가 일정 수준 이상으로 증가하지 않음(포화)==','단순확산은 농도 차에 ==비례==하여 속도가 계속 증가']],
 ['h','삼투'],
 ['p','==반투과성막==(설탕은 통과 X, 물은 통과 O)을 사이에 두고 ==저농도 → 고농도== 용액으로 ==물이 이동==하는 현상 (에너지 사용 X)\n삼투가 일어날 때 반투과성막에 작용하는 압력 = ==삼투압=='],
 ['tbl',['용액','삼투압 비교','적혈구(동물 세포)','적양파 세포(식물 세포)'],[['등장액','세포액과 ==같음==','부피 변화 없음','변화 없음'],['고장액','세포액보다 ==높음==','물이 빠져나가 ==쪼그라듦==','물이 빠져나가 ==원형질분리== (세포막이 세포벽에서 떨어짐)'],['저장액','세포액보다 ==낮음==','물이 들어와 부피가 커지다 터짐 = ==용혈==','물이 들어와 ==팽윤== (세포벽 때문에 일정 부피 이상 커지지 않음)']]],
 ['key','식물 세포의 흡수력','==팽압==: 식물 세포 안으로 물이 들어올 때 세포 내부에서 ==세포벽이 받는 압력==\n==흡수력 = 삼투압 − 팽압== (물을 흡수하려는 힘)\n물을 흡수하면 ==팽압↑, 삼투압↓, 흡수력↓== → ==팽압 = 삼투압이 되면 흡수력 0== (최대 팽윤 상태, 더 이상 물을 흡수하지 않음)\n원형질분리된 세포를 저장액에 넣으면 최대 팽윤 상태까지 물을 흡수'],
 ['p','등장액에서도 물은 이동하지만 ==들어오는 양 = 나가는 양==이라 부피 변화가 없어 보일 뿐'],
 ['h','탐구: 적양파 세포의 삼투 현상'],
 ['p','생리식염수(0.9 %)에서 정상 → ==10 % 소금물(고장액)==에서 원형질분리 → ==증류수(저장액)==에서 원형질 복원·팽윤\n적양파는 ==액포의 색소== 덕분에 액포 크기 변화를 관찰하기 쉬움'],
 ['h','능동수송'],
 ['p','==농도 기울기를 거슬러 저농도 → 고농도==로 이동, ==운반체단백질== 이용, ==ATP(세포의 에너지) 사용==\n예: 뉴런의 ==Na⁺–K⁺ 펌프== (Na⁺을 세포 밖으로 내보내고 K⁺을 세포 안으로 들여옴 → 이온 농도 차 유지), 소장의 양분 흡수, 뿌리털의 무기양분 흡수'],
 ['h','세포내섭취와 세포외배출'],
 ['p','단백질처럼 ==크기가 큰 물질==은 확산·능동수송으로 통과 불가 → 막으로 둘러싼 ==소낭==으로 이동, ==에너지 사용=='],
 ['tbl',['구분','내용','예'],[['세포내섭취','세포 밖 물질을 세포막으로 감싸 소낭을 만들어 ==안으로==','==식세포작용==(큰 고체, 예: 백혈구가 세균을 삼킴), ==음세포작용==(액체에 녹은 물질)'],['세포외배출','세포 안 ==소낭이 세포막과 융합==하여 물질을 ==밖으로==','이자세포의 ==인슐린 분비==, 노폐물 배출']]],
 ['tip','이동 방식 구분 표가 단골: **에너지 사용? / 농도 기울기 방향? / 막단백질 이용?** 확산 = 에너지 X·높→낮, 능동수송 = 에너지 O·낮→높. **고장액 → 동물 쪼그라듦·식물 원형질분리, 저장액 → 동물 용혈·식물 팽윤.** 흡수력 = 삼투압 − 팽압!']]};
CPQ['0-2']=[
 {t:'sh',g:A,q:'세포막의 인지질 이중층에서 인산을 포함한 머리 부분은 [빈칸]성이다.',a:['친수'],m:'친수',e:'머리는 친수성, 꼬리(지방산)는 소수성이에요. 소수성 꼬리는 안쪽에서 서로 마주 봐요.'},
 {t:'ox',g:A,q:'세포막의 인지질과 막단백질은 특정 위치에 고정되어 움직이지 않는다.',a:false,e:'인지질과 막단백질은 수평으로 자유롭게 이동할 수 있어서 세포막을 유동모자이크막이라고 해요.'},
 {t:'mc',g:A,q:'세포 밖의 특정 화학 물질을 인식하여 세포 안으로 신호를 전달하는 막단백질은?',o:['수송단백질','수용체단백질','효소단백질','통로단백질','운반체단백질'],a:1,e:'수송단백질은 물질 이동, 효소단백질은 물질대사에 관여해요.'},
 {t:'sh',g:B,q:'물질이 농도가 높은 쪽에서 낮은 쪽으로 이동하며 세포가 에너지를 사용하지 않는 현상을 [빈칸]이라고 한다.',a:['확산'],m:'확산',e:'확산에는 단순확산과 촉진확산이 있어요.'},
 {t:'mc',g:B,q:'폐포와 모세혈관 사이에서 산소가 이동하는 방식은?',o:['단순확산','촉진확산','능동수송','세포내섭취','세포외배출'],a:0,e:'산소와 이산화 탄소는 인지질 이중층을 직접 통과하는 단순확산으로 이동해요.'},
 {t:'ox',g:B,q:'촉진확산에서는 운반체단백질이나 통로단백질이 이용된다.',a:true,e:'촉진확산은 수송단백질(통로단백질, 운반체단백질)을 통해 일어나요.'},
 {t:'sh',g:C,q:'식물 세포를 고장액에 넣었을 때, 세포막이 세포벽에서 떨어지는 현상을 [빈칸]이라고 한다.',a:['원형질분리'],m:'원형질분리',e:'고장액에서 세포 안의 물이 빠져나가 세포질의 부피가 작아져요.'},
 {t:'mc',g:C,q:'적혈구를 저장액에 넣었을 때 나타나는 현상은?',o:['쪼그라든다.','변화가 없다.','부피가 커지다가 터진다.','원형질분리가 일어난다.','부피가 일정하게 유지된다.'],a:2,e:'저장액에서는 물이 들어와 부피가 커지다 세포막이 터지는데, 이를 용혈이라고 해요.'},
 {t:'mc',g:D,q:'Na⁺-K⁺ 펌프에 의한 이온의 이동 방식은?',o:['단순확산','촉진확산','삼투','능동수송','세포외배출'],a:3,e:'Na⁺-K⁺ 펌프는 ATP를 사용하여 농도 기울기를 거슬러 이온을 이동시키는 능동수송이에요.'},
 {t:'ox',g:D,q:'이자세포에서 인슐린을 혈액으로 분비하는 것은 세포외배출에 해당한다.',a:true,e:'세포 안 소낭이 세포막과 융합하여 소낭 속 물질을 밖으로 내보내요. 이때 세포의 에너지가 사용돼요.'},
 {lv:'x',t:'mc',g:A,q:'세포막에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. 인지질은 막의 기본 구조를 형성한다.\nㄴ. 막단백질은 막의 기능을 결정한다.\nㄷ. 인지질 이중층에서 소수성 꼬리는 세포 바깥쪽을 향한다.',o:['ㄱ','ㄴ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ'],a:2,e:'소수성 꼬리는 서로 마주 보고, 친수성 머리가 세포 안팎을 향해요.'},
 {lv:'x',t:'mc',g:A,q:'사람 세포와 쥐 세포의 막단백질을 각각 다른 형광 물질로 표지한 뒤 융합시켰더니, 융합 직후에는 각 색의 형광이 따로 분포하다가 1시간 후에는 섞여서 고르게 분포하였다. 이 실험으로 알 수 있는 세포막의 특성은?',o:['선택적 투과성','막단백질의 유동성','세포벽의 단단함','막단백질의 효소 활성','삼투압의 변화'],a:1,e:'막단백질이 인지질 이중층에서 수평으로 이동해 섞였으므로 유동성이 있음을 알 수 있어요.'},
 {lv:'x',t:'mc',g:B,q:'표는 물질 이동 방식 (가)~(다)의 특징을 나타낸 것이다. (가)~(다)는 단순확산, 촉진확산, 능동수송을 순서 없이 나타낸 것이다. ○는 있음, ×는 없음이다.\n\n[표]\n\n(가)~(다)를 옳게 짝지은 것은?',tb:{h:['특징','(가)','(나)','(다)'],r:[['세포가 에너지(ATP)를 사용한다.','×','×','○'],['막단백질을 이용한다.','×','○','○'],['농도 기울기에 따라 이동한다.','○','○','×']]},o:['단순확산, 촉진확산, 능동수송','촉진확산, 단순확산, 능동수송','능동수송, 촉진확산, 단순확산','단순확산, 능동수송, 촉진확산','촉진확산, 능동수송, 단순확산'],a:0,e:'(가)는 막단백질 없이 농도 기울기대로 이동하는 단순확산, (나)는 촉진확산, (다)는 에너지를 쓰며 농도 기울기를 거스르는 능동수송이에요.'},
 {lv:'x',t:'mc',g:B,q:'설탕은 통과시키지 못하고 물은 통과시키는 반투과성막으로 U자관을 반으로 나누고, 왼쪽에는 5 % 설탕 용액, 오른쪽에는 10 % 설탕 용액을 같은 높이로 넣었다. 충분한 시간이 지난 후의 설명으로 옳은 것은?',o:['오른쪽 수면이 낮아진다.','왼쪽 수면이 높아진다.','물이 왼쪽에서 오른쪽으로 이동하여 오른쪽 수면이 높아진다.','설탕이 오른쪽에서 왼쪽으로 이동한다.','물의 이동이 일어나지 않는다.'],a:2,e:'물은 저농도(왼쪽)에서 고농도(오른쪽) 쪽으로 이동하므로 오른쪽 수면이 높아져요.'},
 {lv:'x',t:'mc',g:B,q:'다음은 세포 안팎의 농도 차에 따른 물질 X의 이동 속도를 측정한 자료이다.\n\n[표]\n\n이에 대한 설명으로 옳은 것은?',tb:{h:['농도 차','1','2','3','4','5'],r:[['이동 속도','2','4','6','7','7']]},o:['X는 단순확산으로만 이동한다.','농도 차가 4 이상에서는 이동에 관여하는 수송단백질이 모두 사용되고 있을 것이다.','농도 차가 커질수록 이동 속도는 항상 비례하여 증가한다.','X는 능동수송으로 이동한다.','X는 에너지를 사용하여 이동한다.'],a:1,e:'속도가 일정 수준에서 더 증가하지 않는 것은 수송단백질이 포화되었기 때문이므로 촉진확산이에요.'},
 {lv:'x',t:'mc',g:C,q:'표는 사람의 적혈구와 적양파 세포를 용액 A와 B에 각각 넣었을 때의 변화이다. 세포액의 삼투압은 두 세포에서 같다.\n\n[표]\n\n이에 대한 설명으로 옳은 것은?',tb:{h:['용액','적혈구','적양파 세포'],r:[['A','부피가 작아짐','원형질분리가 일어남'],['B','부피가 커지다가 터짐','부피가 커지지만 한계가 있음']]},o:['A는 저장액이다.','B는 고장액이다.','A는 세포액보다 삼투압이 높은 용액이다.','B에서 적양파 세포에는 용혈이 일어났다.','A에서는 적양파 세포로 물이 들어온다.'],a:2,e:'A는 고장액, B는 저장액이에요. 적혈구가 터지는 현상은 용혈, 식물 세포가 커지는 것은 팽윤이에요.'},
 {lv:'x',t:'mc',g:C,q:'식물 세포를 어떤 용액에 넣었더니 삼투압이 10 기압이었던 세포의 팽압이 4 기압이 되었다. 이때 이 세포의 흡수력은? (단, 이 세포의 삼투압은 변하지 않았다고 가정한다.)',o:['4 기압','6 기압','10 기압','14 기압','0 기압'],a:1,e:'흡수력 = 삼투압 − 팽압 = 10 − 4 = 6 기압이에요.'},
 {lv:'x',t:'mc',g:C,q:'원형질분리가 일어난 식물 세포를 증류수에 넣어 최대 팽윤 상태가 될 때까지 둘 때, 변화로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. 팽압이 증가한다.\nㄴ. 삼투압이 감소한다.\nㄷ. 흡수력이 증가한다.',o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:1,e:'물을 흡수하면 팽압은 증가하고 삼투압은 감소하며 흡수력은 줄어 최대 팽윤 상태에서 0이 돼요.'},
 {lv:'x',t:'mc',g:D,q:'표는 물질 이동 방식 A~C에서 특징을 나타낸 것이다. A~C는 능동수송, 세포내섭취, 세포외배출을 순서 없이 나타낸 것이다.\n\n[표]\n\n이에 대한 설명으로 옳은 것은?',tb:{h:['이동 방식','소낭 형성','세포가 에너지 사용'],r:[['A','×','○'],['B','○','○'],['C','○','○']]},o:['A는 확산이다.','B와 C는 모두 소낭을 이용하며, 둘 다 에너지를 사용한다.','C는 인지질 이중층을 직접 통과하는 방식이다.','A는 농도 기울기 방향으로 일어난다.','B와 C에는 운반체단백질만 이용된다.'],a:1,e:'A는 운반체단백질을 이용하는 능동수송이고, B와 C는 소낭을 이용하는 세포내섭취·세포외배출이에요.'},
 {lv:'x',t:'mc',g:D,q:'백혈구가 세균을 잡아먹는 현상과 이자세포가 인슐린을 분비하는 현상을 순서대로 옳게 짝지은 것은?',o:['식세포작용(세포내섭취), 세포외배출','음세포작용, 세포외배출','세포외배출, 식세포작용','단순확산, 촉진확산','능동수송, 삼투'],a:0,e:'세균 같은 큰 고체 물질을 삼키는 것은 식세포작용이고, 인슐린 분비는 세포외배출이에요.'}
];
CPMK['0-2']=[
 {g:A,q:'다음은 세포막에 대한 학생들의 대화이다.\n\n갑: 세포막을 전자 현미경으로 보면 진한 선이 두 겹으로 보이는데, 이는 인지질 이중층 때문이야.\n을: 인지질의 소수성 꼬리는 세포 안팎의 물과 접하고 있어.\n병: 막단백질에는 수송단백질, 수용체단백질, 효소단백질 등이 있어.\n\n옳게 말한 학생만을 고른 것은?',o:['갑','을','병','갑, 병','을, 병'],a:3,e:'물과 접하는 것은 친수성 머리이고, 소수성 꼬리는 서로 마주 봐요.'},
 {g:A,q:'표는 세포막 구성 성분 (가)~(다)의 특징이다.\n\n[표]\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. (가)는 인지질이다.\nㄴ. (나)는 수송단백질이다.\nㄷ. (다)는 세포를 인식하는 데 이용될 수 있다.',tb:{h:['성분','특징'],r:[['(가)','친수성 머리와 소수성 꼬리로 이루어지며 이중층을 형성함'],['(나)','막을 통한 물질의 이동에 관여하는 막단백질'],['(다)','막단백질에 붙어 있으며 세포 인식에 관여할 수 있음']]},o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:4,e:'(다)는 막단백질에 붙은 탄수화물이에요.'},
 {g:B,q:'표는 세포막을 통한 물질 이동 방식 (가)~(다)의 특징을 나타낸 것이다. (가)~(다)는 단순확산, 촉진확산, 능동수송을 순서 없이 나타낸 것이다.\n\n[표]\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. (가)에서 포도당은 운반체단백질을 통해 이동한다.\nㄴ. (나)는 폐포와 모세혈관 사이에서 산소가 이동하는 방식이다.\nㄷ. (다)는 농도 기울기를 거슬러 이동하며 ATP를 사용한다.',tb:{h:['방식','막단백질 이용','에너지 사용','이동 방향'],r:[['(가)','○','×','고농도 → 저농도'],['(나)','×','×','고농도 → 저농도'],['(다)','○','○','저농도 → 고농도']]},o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:4,e:'(가) 촉진확산, (나) 단순확산, (다) 능동수송이에요.'},
 {g:B,q:'다음은 물질 X의 세포막 통과에 대한 실험이다.\n\n[실험 결과]\n• 세포 밖 X의 농도가 세포 안보다 높을 때 X가 세포 안으로 이동한다.\n• X의 이동에 수송단백질이 필요하다.\n• 세포의 호흡을 억제하여 ATP 공급을 막아도 X의 이동은 계속된다.\n\nX의 이동 방식으로 가장 적절한 것은?',o:['단순확산','촉진확산','능동수송','세포내섭취','세포외배출'],a:1,e:'농도 기울기를 따라 이동하고 수송단백질이 필요하며 ATP가 필요 없으므로 촉진확산이에요.'},
 {g:B,q:'다음은 U자관 실험이다.\n\n[실험]\n• 반투과성막(물은 통과, 설탕은 통과하지 못함)으로 U자관의 중앙을 나눈다.\n• 왼쪽(Ⅰ)에는 10 % 설탕 용액을, 오른쪽(Ⅱ)에는 20 % 설탕 용액을 같은 높이로 넣는다.\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. 물은 Ⅰ에서 Ⅱ로 더 많이 이동한다.\nㄴ. 시간이 지나면 Ⅱ의 수면이 Ⅰ보다 높아진다.\nㄷ. 이 현상이 일어날 때 세포는 에너지를 사용하지 않는다.',o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:4,e:'삼투는 저농도에서 고농도로 물이 이동하는 현상이며 에너지를 사용하지 않아요.'},
 {g:C,q:'표는 용액 (가)~(다)에 적혈구를 넣었을 때 적혈구의 상대적 부피 변화를 나타낸 것이다. (가)~(다)는 등장액, 고장액, 저장액을 순서 없이 나타낸 것이다.\n\n[표]\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. (가)는 저장액이다.\nㄴ. (나)에서 적혈구로 들어오는 물의 양과 나가는 물의 양은 같다.\nㄷ. (다)는 적혈구 속 세포액보다 삼투압이 높은 용액이다.',tb:{h:['용액','(가)','(나)','(다)'],r:[['적혈구 부피 변화','점점 커지다 터짐','변화 없음','작아짐']]},o:['ㄱ','ㄴ','ㄱ, ㄴ','ㄱ, ㄷ','ㄱ, ㄴ, ㄷ'],a:4,e:'(가) 저장액, (나) 등장액, (다) 고장액이에요. 등장액에서도 물은 같은 양씩 오가요.'},
 {g:C,q:'다음은 식물 세포 (가)와 (나)의 상태를 나타낸 자료이다.\n\n[표]\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. (가)는 최대 팽윤 상태이다.\nㄴ. (나)의 흡수력은 6이다.\nㄷ. (나)는 (가)보다 물을 흡수하는 힘이 크다.',tb:{h:['세포','삼투압','팽압'],r:[['(가)','8','8'],['(나)','10','4']]},o:['ㄱ','ㄴ','ㄷ','ㄱ, ㄴ','ㄱ, ㄴ, ㄷ'],a:4,e:'흡수력 = 삼투압 − 팽압이므로 (가)는 0(최대 팽윤), (나)는 6이에요.'},
 {g:C,q:'다음은 적양파 세포를 이용한 삼투 실험이다.\n\n[실험]\n• 적양파 표피 조각을 생리식염수에 올려 관찰하였더니 정상으로 보였다.\n• (가) 10 % 소금물을 떨어뜨렸더니 세포질이 줄어들면서 세포막이 세포벽에서 떨어졌다.\n• (나) 이후 증류수를 떨어뜨렸더니 세포가 원래 상태로 돌아왔다.\n\n이에 대한 설명으로 옳지 않은 것은?',o:['(가)에서 세포 안의 물이 빠져나갔다.','(가)의 소금물은 세포액보다 삼투압이 높다.','(가)에서 일어난 현상은 원형질분리이다.','(나)의 증류수는 세포액보다 삼투압이 낮다.','(나)에서 세포가 터졌다.'],a:4,e:'식물 세포는 세포벽이 있어 저장액에서도 터지지 않고 팽윤만 일어나요.'},
 {g:C,q:'식물 세포의 팽압, 삼투압, 흡수력의 관계에 대한 설명으로 옳은 것은?',o:['흡수력은 팽압에서 삼투압을 뺀 값이다.','물을 흡수하면 삼투압이 증가한다.','삼투압과 팽압이 같으면 흡수력은 0이다.','팽압은 세포막이 세포벽에서 받는 압력이다.','물을 흡수할수록 흡수력은 커진다.'],a:2,e:'흡수력 = 삼투압 − 팽압이고, 팽압은 세포 내부로부터 세포벽이 받는 압력이에요. 물을 흡수하면 흡수력은 작아져요.'},
 {g:D,q:'다음은 Na⁺-K⁺ 펌프의 작동 과정에 대한 설명이다.\n\n(가) 세포 안의 Na⁺이 펌프에 결합한다.\n(나) ATP가 사용되어 펌프의 구조가 바뀌고 Na⁺이 세포 밖으로 방출된다.\n(다) 세포 밖의 K⁺이 펌프에 결합한다.\n(라) 펌프의 구조가 원래대로 돌아가고 K⁺이 세포 안으로 들어온다.\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. Na⁺-K⁺ 펌프는 운반체단백질이다.\nㄴ. Na⁺은 농도 기울기를 거슬러 이동한다.\nㄷ. 이 과정은 세포 안팎의 이온 농도 차이를 유지한다.',o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:4,e:'Na⁺-K⁺ 펌프는 ATP를 사용하는 능동수송으로, 이온 농도 차이를 유지해요.'},
 {g:D,q:'표는 세포막을 통한 물질 이동 방식 A~D에서 특징 ㉠~㉢의 유무를 나타낸 것이다. A~D는 단순확산, 촉진확산, 능동수송, 세포외배출을 순서 없이 나타낸 것이고, ㉠~㉢은 에너지 사용, 막단백질 이용, 소낭 형성을 순서 없이 나타낸 것이다. ○는 있음, ×는 없음이다.\n\n[표]\n\n이에 대한 설명으로 옳은 것은?',tb:{h:['구분','㉠','㉡','㉢'],r:[['A','×','×','×'],['B','×','○','×'],['C','○','○','×'],['D','○','×','○']]},o:['A는 촉진확산이다.','B는 단순확산이다.','C는 능동수송이다.','D는 막단백질을 이용한다.','㉢은 에너지 사용이다.'],a:2,e:'소낭을 만드는 D가 세포외배출, 아무 특징이 없는 A는 단순확산, 막단백질만 이용하는 B는 촉진확산, 에너지와 막단백질을 쓰는 C가 능동수송이에요. ㉠은 에너지 사용, ㉡은 막단백질 이용, ㉢은 소낭 형성이에요.'},
 {g:D,q:'다음은 세포 밖의 물질을 세포 안으로 이동시키는 방식에 대한 설명이다.\n\n• 방식 (가): 미생물이나 세포 조각 같은 큰 고체 물질을 막으로 감싸 안으로 끌어들인다.\n• 방식 (나): 액체에 녹아 있는 물질을 안으로 이동시킨다.\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. (가)는 식세포작용이다.\nㄴ. (나)는 음세포작용이다.\nㄷ. (가)와 (나)에는 세포의 에너지가 사용되지 않는다.',o:['ㄱ','ㄴ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ'],a:2,e:'세포내섭취(식세포작용, 음세포작용)에는 세포의 에너지가 사용돼요.'},
 {g:B,q:'뉴런에서 일어나는 신경 자극 전도 시 Na⁺ 통로를 통한 Na⁺의 이동 방식과 같은 방식으로 이동하는 것은?',o:['소장에서 양분이 흡수되는 것','폐포에서 모세혈관으로 산소가 이동하는 것','혈액의 포도당이 운반체단백질을 통해 세포 안으로 이동하는 것','백혈구가 세균을 삼키는 것','이자세포에서 인슐린이 분비되는 것'],a:2,e:'Na⁺ 통로를 통한 이동은 촉진확산이에요. 혈액의 포도당이 운반체단백질로 이동하는 것도 촉진확산이에요.'}
];
Object.assign(TIPS,{[A]:'세포막 = 인지질 이중층(친수성 머리 바깥, 소수성 꼬리 안쪽) + 막단백질(수송·수용체·효소·세포 인식). 유동모자이크막, 선택적 투과성!',[B]:'확산(높→낮, 에너지 X): 단순확산(직접 통과: O₂·CO₂) / 촉진확산(수송단백질: 포도당·Na⁺ 통로). 촉진확산은 속도가 포화! 삼투 = 물이 저농도 → 고농도.',[C]:'고장액: 적혈구 쪼그라듦 / 식물 원형질분리. 저장액: 적혈구 용혈 / 식물 팽윤(세포벽 때문에 안 터짐). 흡수력 = 삼투압 − 팽압, 팽압 = 삼투압이면 흡수력 0!',[D]:'능동수송(저→고, 운반체단백질, ATP): Na⁺-K⁺ 펌프. 세포내섭취(식세포·음세포)/세포외배출은 소낭 이용, 에너지 사용!'});
})();
// ===== Ⅱ. 물질대사와 에너지 =====
// ----- 01 세포의 물질대사와 에너지 (교과서 56~65쪽) -----
(()=>{const A='물질대사와 에너지 출입',B='광합성·세포호흡과 에너지 전환',C='ATP',D='에너지대사의 균형';
NOTE[CPN]['1-0']={pg:CPPG(2,1,56,65),b:[
 ['h','01 생명활동과 물질대사'],
 ['def','물질대사','생명체에서 ==생명을 유지하기 위해 일어나는 화학 반응==\n==효소==가 관여하고 ==에너지의 출입==이 함께 일어남 → ==에너지대사==라고도 함'],
 ['tbl',['구분','동화작용','이화작용'],[['반응','작은 분자 → ==큰 분자 합성==','큰 분자 → ==작은 분자 분해=='],['에너지','==흡열 반응== (생성물의 에너지 > 반응물의 에너지)','==발열 반응== (생성물의 에너지 < 반응물의 에너지) → 에너지 방출'],['예','==광합성==(CO₂ + H₂O → 포도당), 포도당 → 녹말, 아미노산 → 단백질','==세포호흡==(포도당 → CO₂ + H₂O)']]],
 ['p','세포는 물질대사로 ==에너지를 얻고==, 세포 구성 물질이나 생리작용을 조절하는 물질을 생산'],
 ['h','02 생명활동에 필요한 에너지 공급'],
 ['p','모든 생물은 ==유기물(탄수화물·지방·단백질)을 분해==하여 에너지를 얻음 (유기물 속에 ==화학 에너지==로 저장)\n유기물은 근본적으로 ==식물의 광합성==으로 제공됨'],
 ['flow',['태양의 ==빛에너지==','==광합성(엽록체)== 빛에너지 → 유기물의 화학 에너지','유기물이 먹이사슬을 따라 사람·동물에게 전달','==세포호흡(세포질, 마이토콘드리아)== 유기물 분해 → 방출된 에너지의 일부가 ==ATP==에 저장','ATP 에너지를 생명활동에 사용']],
 ['key','모든 생명활동 에너지의 근원','==태양의 빛에너지==가 광합성으로 유기물에 저장 → 세포호흡으로 방출·사용\n세포호흡: 유기물 분해로 에너지 방출, 그 ==일부만== ATP에 저장 (나머지는 열 등으로 방출)'],
 ['h','ATP'],
 ['def','ATP (아데노신 3인산)','생명활동에 ==직접 사용되는 에너지원==\n구조: ==아데노신(라이보스 + 아데닌) + 인산기 3개==\n인산기와 인산기 사이 = ==고에너지 인산 결합==, 끊어지면 다량의 에너지 방출'],
 ['flow',['==ATP== (인산기 3개)','맨 끝 인산기가 떨어짐 → 약 ==7.3 kcal/mol== 방출','==ADP== (인산기 2개) + 무기 인산(Pi)','세포호흡의 에너지로 ADP + Pi → ATP ==재합성==']],
 ['ul',['ATP → ADP + Pi (에너지 ==방출==) / ADP + Pi → ATP (에너지 ==저장==, 세포호흡 에너지 이용)','ATP를 분해해 얻은 에너지는 ==물질 합성==(단백질·핵산·인지질), ==능동수송==(Na⁺-K⁺ 펌프), ==기계적 활동==(근육 수축, 섬모·편모 운동, 세포분열 시 염색체 이동, 시냅스소포 이동)에 이용']],
 ['p','모든 생명체가 ATP를 공통의 에너지원으로 사용 → 에너지 이용의 ==효율성과 통일성=='],
 ['h','탐구: 발아 중인 콩'],
 ['p','발아 중인 콩(챔버 A)은 마른 콩(챔버 B)보다 ==CO₂ 방출량과 온도 상승==이 큼 → 활발한 ==세포호흡==(물질대사)과 ==열 방출==(에너지대사)\n물질대사와 에너지대사는 ==함께== 일어난다는 것을 확인'],
 ['h','03 에너지대사의 균형'],
 ['tbl',['용어','뜻'],[['기초대사량','==생명 유지에 필요한 최소한의 에너지양== (체중·성별·연령에 따라 다름, 보통 성인 남성 체중 1 kg당 1시간에 약 1 kcal, 여성 약 0.9 kcal)'],['활동대사량','기초대사량 외에 ==공부·운동 등 활동==에 소모되는 에너지양'],['1일 대사량','하루 동안 소비하는 ==에너지 총량== = 기초대사량 + 활동대사량 + 음식물의 소화·흡수에 필요한 에너지']]],
 ['p','1일 대사량 구성비: ==기초대사량 60~70 %==, ==활동대사량 20~35 %==, ==소화·흡수 5~10 %=='],
 ['vs',['섭취량 > 소비량','남는 에너지를 ==지방으로 저장== → ==체중 증가==, 비만'],['섭취량 < 소비량','저장된 ==지방·근육 단백질 분해== → ==체중 감소==, 영양실조·성장 장애']],
 ['p','섭취량 = 소비량이면 에너지 균형 → 균형 잡힌 식사, 규칙적인 운동, 활동량 늘리기\n특정 활동의 에너지 소비량(kcal) = ==활동 유형별 소비량(kcal/kg·h) × 몸무게(kg) × 활동 시간(h)=='],
 ['tip','**동화 = 흡열(합성), 이화 = 발열(분해)**, 그래프에서는 **반응물 에너지 > 생성물 에너지 → 이화**! ATP는 **아데노신 + 인산기 3개**, 직접적 에너지원, **ATP → ADP + Pi에서 에너지 방출**. 세포호흡 에너지의 **일부만** ATP에 저장. 활동 에너지 소비량 = **소비량 × 체중 × 시간**.']]};
CPQ['1-0']=[
 {t:'sh',g:A,q:'생명체에서 생명을 유지하기 위해 일어나는 화학 반응을 [빈칸]라고 한다.',a:['물질대사'],m:'물질대사',e:'물질대사에는 효소가 관여하고 에너지의 출입이 함께 일어나요.'},
 {t:'mc',g:A,q:'동화작용에 해당하는 것은?',o:['포도당이 이산화 탄소와 물로 분해되는 과정','이산화 탄소와 물로 포도당을 합성하는 과정','녹말이 엿당으로 분해되는 과정','단백질이 아미노산으로 분해되는 과정','지방이 지방산과 글리세롤로 분해되는 과정'],a:1,e:'광합성은 작은 분자인 이산화 탄소와 물로 큰 분자인 포도당을 합성하는 동화작용이에요.'},
 {t:'ox',g:A,q:'이화작용은 에너지가 흡수되는 흡열 반응이다.',a:false,e:'이화작용은 에너지가 방출되는 발열 반응이고, 동화작용이 흡열 반응이에요.'},
 {t:'mc',g:B,q:'세포호흡이 일어나는 장소로 옳은 것은?',o:['엽록체','세포질과 마이토콘드리아','핵과 골지체','리소솜과 액포','소포체와 라이보솜'],a:1,e:'세포호흡은 세포질과 마이토콘드리아에서 일어나요.'},
 {t:'sh',g:B,q:'광합성에서는 [빈칸]에너지가 화학 에너지로 전환되어 유기물에 저장된다.',a:['빛','태양'],m:'빛',e:'모든 생명활동 에너지는 결국 태양의 빛에너지에서 유래해요.'},
 {t:'sh',g:C,q:'ATP는 아데노신에 [빈칸]개의 인산기가 결합한 구조이다.',a:['3','세','삼'],m:'3',e:'아데노신 3인산(ATP)이에요. 마지막 인산기가 떨어지면 ADP가 돼요.'},
 {t:'mc',g:C,q:'ATP의 설명으로 옳지 않은 것은?',o:['생명활동에 직접 사용되는 에너지원이다.','아데노신은 라이보스와 아데닌이 결합한 것이다.','인산기 사이의 고에너지 인산 결합이 끊어지면 에너지가 방출된다.','ATP가 ADP로 분해될 때 에너지가 흡수된다.','세포호흡에서 방출된 에너지로 ADP와 무기 인산이 ATP로 합성된다.'],a:3,e:'ATP가 ADP와 무기 인산으로 분해될 때 에너지가 방출돼요.'},
 {t:'ox',g:C,q:'능동수송에 필요한 에너지는 ATP로부터 공급받는다.',a:true,e:'ATP는 물질 합성, 능동수송, 기계적 활동 등에 사용돼요.'},
 {t:'sh',g:D,q:'생명활동을 유지하는 데 필요한 최소한의 에너지양을 [빈칸]이라고 한다.',a:['기초대사량'],m:'기초대사량',e:'공부나 운동 등 활동에 소모되는 에너지양은 활동대사량이에요.'},
 {t:'ox',g:D,q:'섭취한 음식물에서 얻은 에너지양이 소비한 에너지양보다 많은 상태가 지속되면 체중이 감소한다.',a:false,e:'섭취량 > 소비량이면 남는 에너지가 지방으로 저장되어 체중이 증가해요.'},
 {lv:'x',t:'mc',g:A,q:'표는 사람의 간세포에서 일어나는 물질대사 (가)와 (나)의 반응물과 생성물의 에너지를 나타낸 것이다.\n\n[표]\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. (가)는 동화작용이다.\nㄴ. (나)에서는 에너지가 방출된다.\nㄷ. 세포호흡은 (나)와 같은 유형이다.',tb:{h:['물질대사','반응물의 에너지','생성물의 에너지'],r:[['(가)','낮음','높음'],['(나)','높음','낮음']]},o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:4,e:'(가)는 생성물 에너지가 더 높은 동화작용(흡열), (나)는 생성물 에너지가 더 낮은 이화작용(발열)이에요. 세포호흡은 이화작용이에요.'},
 {lv:'x',t:'mc',g:A,q:'물질대사에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. 효소가 관여한다.\nㄴ. 에너지의 출입이 함께 일어난다.\nㄷ. 동화작용과 이화작용으로 구분된다.',o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:4,e:'물질대사는 효소의 도움으로 일어나고 에너지대사를 동반하며 동화·이화로 나뉘어요.'},
 {lv:'x',t:'mc',g:A,q:'다음 중 이화작용에 해당하는 것만을 있는 대로 고른 것은?\n\nㄱ. 포도당 여러 개가 결합하여 녹말이 만들어진다.\nㄴ. 포도당이 분해되어 이산화 탄소와 물이 생성된다.\nㄷ. 아미노산이 결합하여 단백질이 합성된다.\nㄹ. 단백질이 아미노산으로 분해된다.',o:['ㄴ','ㄴ, ㄹ','ㄱ, ㄷ','ㄱ, ㄴ','ㄷ, ㄹ'],a:1,e:'큰 분자를 작은 분자로 분해하는 ㄴ, ㄹ이 이화작용이에요.'},
 {lv:'x',t:'mc',g:B,q:'광합성과 세포호흡에 대한 설명으로 옳은 것은?',o:['광합성은 이화작용이고 세포호흡은 동화작용이다.','광합성에서는 화학 에너지가 빛에너지로 전환된다.','세포호흡에서 방출된 에너지는 모두 ATP에 저장된다.','광합성은 세포질에서, 세포호흡은 엽록체에서 일어난다.','모든 생물의 생명활동 에너지는 태양 에너지에서 유래한다.'],a:4,e:'세포호흡에서 방출된 에너지 중 일부만 ATP에 저장돼요. 광합성은 동화작용, 세포호흡은 이화작용이에요.'},
 {lv:'x',t:'mc',g:B,q:'태양 에너지의 이동을 나타낸 (가)~(다)를 옳게 짝지은 것은?\n\n태양의 빛에너지 →(가)→ 유기물의 화학 에너지 →(나)→ (다)에 저장된 화학 에너지 → 생명활동',o:['광합성, 세포호흡, ATP','세포호흡, 광합성, ATP','광합성, 세포호흡, 포도당','세포호흡, 광합성, 녹말','광합성, ATP, 세포호흡'],a:0,e:'빛에너지는 광합성으로 유기물에 저장되고, 세포호흡에서 방출되어 ATP에 저장돼 생명활동에 쓰여요.'},
 {lv:'x',t:'mc',g:C,q:'ATP와 ADP의 상호 전환에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. ATP → ADP + Pi 과정에서 에너지가 방출된다.\nㄴ. ADP + Pi → ATP 과정에는 세포호흡에서 방출된 에너지가 이용된다.\nㄷ. ADP는 ATP보다 인산기가 1개 더 많다.',o:['ㄱ','ㄴ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ'],a:2,e:'ADP는 인산기가 2개로, ATP(3개)보다 1개 적어요.'},
 {lv:'x',t:'mc',g:C,q:'ATP의 에너지가 이용되는 세포의 활동만을 <보기>에서 있는 대로 고른 것은?\n\n<보기>\nㄱ. 뉴런에서 Na⁺-K⁺ 펌프에 의한 이온의 이동\nㄴ. 근육의 수축\nㄷ. 폐포와 모세혈관 사이의 산소 이동',o:['ㄱ','ㄴ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ'],a:2,e:'산소의 이동은 단순확산이라 에너지가 필요하지 않아요.'},
 {lv:'x',t:'mc',g:A,q:'발아 중인 콩과 마른 콩을 각각 밀폐된 용기에 넣고 20분 동안 측정한 결과이다.\n\n[표]\n\n이에 대한 설명으로 옳은 것은?',tb:{h:['구분','CO₂ 농도 변화','온도 변화'],r:[['A (발아 중인 콩)','크게 증가','증가'],['B (마른 콩)','거의 없음','거의 없음']]},o:['A에서는 세포호흡이 활발하게 일어난다.','B에서 세포호흡이 더 활발하다.','이 결과는 물질대사에 에너지 출입이 없음을 보여 준다.','A의 온도 증가는 동화작용에 의한 에너지 흡수 때문이다.','B에서는 물질대사가 가장 활발하다.'],a:0,e:'발아 중인 콩에서 세포호흡으로 CO₂가 방출되고 에너지가 열로 방출되어 온도가 올라가요.'},
 {lv:'x',t:'mc',g:D,q:'몸무게가 50 kg인 학생이 공부하기(활동 유형별 에너지 소비량 1.5 kcal/kg·h)를 4시간 하였을 때 소비한 에너지양은?',o:['75 kcal','150 kcal','200 kcal','300 kcal','600 kcal'],a:3,e:'에너지 소비량 = 1.5 × 50 × 4 = 300 kcal예요.'},
 {lv:'x',t:'mc',g:D,q:'다음은 학생 3명의 하루 에너지 섭취량과 소비량이다.\n\n[표]\n\n이 상태가 장기간 지속될 때 체중이 증가할 것으로 예상되는 학생만을 있는 대로 고른 것은?',tb:{h:['학생','섭취량(kcal)','소비량(kcal)'],r:[['갑','2500','2300'],['을','2000','2000'],['병','1800','2200']]},o:['갑','을','병','갑, 을','을, 병'],a:0,e:'섭취량이 소비량보다 많은 갑은 체중이 증가하고, 병은 감소해요.'}
];
CPMK['1-0']=[
 {g:A,q:'표는 물질대사 (가)~(다)의 예이다.\n\n[표]\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. (가)는 동화작용이다.\nㄴ. (나)는 에너지가 방출되는 반응이다.\nㄷ. (다)에서는 반응물의 에너지가 생성물의 에너지보다 낮다.',tb:{h:['물질대사','예'],r:[['(가)','이산화 탄소와 물을 이용하여 포도당을 합성'],['(나)','포도당을 이산화 탄소와 물로 분해'],['(다)','아미노산을 결합하여 단백질을 합성']]},o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:4,e:'(가), (다)는 동화작용(흡열)이므로 생성물의 에너지가 더 높고, (나)는 이화작용(발열)이에요.'},
 {g:A,q:'다음은 사람 세포에서 일어나는 물질대사 X와 Y의 에너지 변화이다.\n\n[표]\n\n이에 대한 설명으로 옳은 것은?',tb:{h:['물질대사','반응물의 에너지','생성물의 에너지'],r:[['X','100','60'],['Y','50','90']]},o:['X는 동화작용이다.','Y는 에너지가 방출된다.','X에서는 에너지가 흡수된다.','Y에서는 에너지 40이 흡수된다.','Y는 세포호흡의 예이다.'],a:3,e:'X는 에너지가 40 방출되는 이화작용이고, Y는 에너지가 40 흡수되는 동화작용이에요.'},
 {g:A,q:'다음은 물질대사에 대한 학생들의 대화이다.\n\n갑: 물질대사에서는 에너지의 출입이 함께 일어나.\n을: 광합성은 이화작용이야.\n병: 동화작용에서는 에너지가 흡수돼.\n\n옳게 말한 학생만을 고른 것은?',o:['갑','을','갑, 병','을, 병','갑, 을, 병'],a:2,e:'광합성은 작은 분자로 큰 분자를 합성하는 동화작용이에요.'},
 {g:B,q:'다음은 광합성과 세포호흡에 대한 설명이다.\n\n(가) 엽록체에서 일어나며 빛에너지를 화학 에너지로 전환한다.\n(나) 유기물을 분해하여 방출된 에너지의 일부를 ATP에 저장한다.\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. (가)는 동화작용이다.\nㄴ. (나)는 세포질과 마이토콘드리아에서 일어난다.\nㄷ. (가)와 (나)에서는 모두 에너지전환이 일어난다.',o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:4,e:'(가)는 광합성, (나)는 세포호흡이에요. 둘 다 에너지전환이 일어나요.'},
 {g:B,q:'생명활동에 필요한 에너지의 흐름에 대한 설명으로 옳은 것은?',o:['사람은 태양의 빛에너지를 직접 이용한다.','식물에 저장된 유기물의 화학 에너지는 먹이사슬을 통해 동물에게 전달된다.','세포호흡에서는 화학 에너지가 빛에너지로 전환된다.','ATP에는 에너지가 저장되지 않는다.','광합성은 모든 생물에서 일어난다.'],a:1,e:'사람은 유기물을 섭취하여 에너지를 얻어요. 광합성은 엽록체가 있는 생물에서만 일어나요.'},
 {g:C,q:'다음은 ATP, ADP, AMP의 인산기 수를 나타낸 것이다.\n\n[표]\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. (가)는 ATP이다.\nㄴ. (다)에는 고에너지 인산 결합이 없다.\nㄷ. (가) → (나) 과정에서 에너지가 방출된다.',tb:{h:['물질','인산기 수'],r:[['(가)','3'],['(나)','2'],['(다)','1']]},o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:4,e:'(가) ATP, (나) ADP, (다) AMP예요. 인산기가 1개인 AMP에는 인산기 사이의 결합이 없어요.'},
 {g:C,q:'다음은 ATP에 대한 설명이다.\n\n• 생명활동에 직접 사용되는 에너지원이다.\n• ㉠ 아데노신에 인산기 3개가 결합한 구조이다.\n• ATP → ADP + Pi 과정에서 약 7.3 kcal/mol의 에너지가 ㉡ (방출/흡수)된다.\n\n㉠의 구성 요소와 ㉡을 옳게 짝지은 것은?',o:['라이보스와 아데닌, 방출','디옥시라이보스와 아데닌, 방출','라이보스와 타이민, 흡수','디옥시라이보스와 타이민, 흡수','라이보스와 아데닌, 흡수'],a:0,e:'아데노신은 라이보스와 아데닌이 결합한 것이고, ATP가 분해될 때 에너지가 방출돼요.'},
 {g:C,q:'다음은 ATP를 이용하는 세포의 활동 (가)~(다)이다.\n\n(가) 아미노산으로 단백질을 합성한다.\n(나) 뉴런에서 Na⁺을 세포 밖으로 내보낸다.\n(다) 근육 세포가 수축한다.\n\n(가)~(다)에서 ATP의 에너지가 이용되는 활동을 옳게 고른 것은?',o:['(가)','(나)','(다)','(가), (나)','(가), (나), (다)'],a:4,e:'ATP는 물질 합성, 능동수송, 기계적 활동에 모두 이용돼요.'},
 {g:D,q:'표는 사람 A와 B의 1일 에너지 소비량 구성이다.\n\n[표]\n\nA의 1일 대사량은?',tb:{h:['구분','기초대사량','활동대사량','소화·흡수'],r:[['A (kcal)','1500','600','200'],['B (kcal)','1300','400','150']]},o:['1500 kcal','1700 kcal','2100 kcal','2300 kcal','2500 kcal'],a:3,e:'1일 대사량 = 기초대사량 + 활동대사량 + 소화·흡수 = 1500 + 600 + 200 = 2300 kcal예요.'},
 {g:D,q:'체중 60 kg인 성인 남성의 기초대사량을 체중 1 kg당 1시간에 1 kcal로 가정할 때, 이 사람의 하루 기초대사량은?',o:['600 kcal','1200 kcal','1440 kcal','1800 kcal','2400 kcal'],a:2,e:'1 kcal × 60 kg × 24시간 = 1440 kcal예요.'},
 {g:D,q:'표는 1일 에너지 섭취량이 같은 두 사람 갑과 을의 1일 대사량 구성을 나타낸 것이다. 두 사람의 섭취량은 각각 2400 kcal이다.\n\n[표]\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. 갑은 체중이 증가할 것이다.\nㄴ. 을은 에너지 균형 상태이다.\nㄷ. 갑의 활동대사량이 을보다 크다.',tb:{h:['구분','기초대사량','활동대사량','소화·흡수','합계'],r:[['갑','1400','500','200','2100'],['을','1500','700','200','2400']]},o:['ㄱ','ㄴ','ㄱ, ㄴ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:2,e:'갑은 섭취(2400) > 소비(2100)로 체중이 증가하고, 을은 균형이에요. 활동대사량은 을이 더 커요.'},
 {g:C,q:'ATP를 소모하는 생명활동만을 <보기>에서 있는 대로 고른 것은?\n\n<보기>\nㄱ. 섬모와 편모의 운동\nㄴ. 세포분열 시 염색체의 이동\nㄷ. 삼투에 의한 물의 이동',o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:1,e:'삼투는 에너지를 사용하지 않아요.'},
 {g:B,q:'광합성과 세포호흡에서 에너지 형태의 전환을 옳게 나타낸 것은?',o:['광합성: 빛에너지 → 화학 에너지, 세포호흡: 화학 에너지 → ATP의 화학 에너지(+열)','광합성: 화학 에너지 → 빛에너지, 세포호흡: 빛에너지 → 화학 에너지','광합성: 열에너지 → 화학 에너지, 세포호흡: 화학 에너지 → 빛에너지','광합성: 빛에너지 → 열에너지, 세포호흡: 열에너지 → ATP','광합성: 화학 에너지 → 열에너지, 세포호흡: 빛에너지 → ATP'],a:0,e:'광합성은 빛에너지를 유기물의 화학 에너지로, 세포호흡은 유기물의 화학 에너지를 ATP의 화학 에너지(와 열)로 전환해요.'}
];
Object.assign(TIPS,{[A]:'동화작용 = 합성·흡열(생성물 에너지 ↑), 이화작용 = 분해·발열(반응물 에너지 ↑). 광합성 = 동화, 세포호흡 = 이화. 물질대사는 효소 관여 + 에너지 출입 동반!',[B]:'태양 빛에너지 →(광합성)→ 유기물의 화학 에너지 →(세포호흡)→ ATP → 생명활동. 세포호흡 에너지는 일부만 ATP에 저장!',[C]:'ATP = 아데노신(라이보스 + 아데닌) + 인산기 3개. ATP → ADP + Pi 에서 에너지 방출(약 7.3 kcal/mol). 물질 합성·능동수송·기계적 활동에 사용, 확산·삼투는 X!',[D]:'1일 대사량 = 기초대사량 + 활동대사량 + 소화·흡수. 활동 소비량(kcal) = 단위 소비량 × 체중 × 시간. 섭취 > 소비 → 체중 증가!'});
})();
// ----- 02 효소 (교과서 66~75쪽) -----
(()=>{const A='효소의 특성과 작용 원리',B='효소의 구성과 종류',C='효소 작용에 영향을 미치는 요인',D='효소 억제제와 효소의 이용';
NOTE[CPN]['1-1']={pg:CPPG(2,2,66,75),b:[
 ['h','01 효소의 특성'],
 ['def','활성화에너지','화학 반응을 일으키는 데 필요한 ==최소한의 에너지=='],
 ['p','체온 정도에서 포도당을 분해할 수 있는 까닭 = ==효소(생체 촉매)가 활성화에너지를 낮춰== 반응이 빨리 일어나게 하기 때문\n==효소가 있어도 반응열(반응물과 생성물의 에너지 차이)은 달라지지 않음==, 효소는 반응 후 변하지 않고 ==재사용=='],
 ['flow',['==기질==(효소와 결합하는 반응물)이 효소의 ==활성부위==에 결합','==효소기질복합체== 형성 → 기질이 변화하여 ==생성물== 생성','반응이 끝나면 효소는 생성물과 분리','분리된 효소가 ==새로운 기질과 다시 결합=='],],
 ['key','기질특이성','효소의 주성분은 ==단백질==(입체 구조 독특) → ==활성부위의 구조에 들어맞는 기질==만 결합\n예: 수크레이스는 ==설탕==은 분해하지만 엿당에는 작용하지 않음 → 물질대사 단계마다 ==여러 종류의 효소== 필요\n효소는 반복 사용되므로 ==적은 양==으로도 효율적'],
 ['h','02 효소의 구성과 종류'],
 ['tbl',['용어','뜻'],[['주효소','효소의 ==단백질== 부분'],['보조인자','효소의 ==비단백질== 부분 — 금속 이온(Fe²⁺, Zn²⁺)과 ==조효소==(바이타민 B₁, NAD⁺, FAD 등)'],['전효소','주효소 + 보조인자 = 완전한 기능을 나타내는 효소']]],
 ['p','조효소는 주효소보다 ==분자가 작고 열에 강하며==, 조효소 하나가 ==여러 주효소==의 작용에 관여\nNAD⁺, FAD: 세포호흡에 관여하는 탈수소효소의 조효소'],
 ['tbl',['효소의 종류','촉매하는 반응'],[['산화환원효소','산화환원반응에서 ==H, O 또는 전자==를 다른 분자에 전달'],['전이효소','특정 기질에서 ==작용기==를 떼어 다른 분자에 전달'],['가수분해효소','==물 분자를 첨가==하여 기질을 분해'],['제거효소','가수분해·산화 이외의 반응으로 작용기를 제거·첨가 (이중결합 생성)'],['이성질화효소','기질의 ==원자 배열==을 바꾸어 성질이 다른 물질로 만듦'],['연결효소','==ATP 에너지를 사용==하여 두 기질 분자를 연결']]],
 ['p','효소 작용의 중요성: 광합성, 세포호흡, 소화, 혈액응고, 식균작용, 해독 등 ==대부분의 생명 반응==에 효소 필요 → 한 종류라도 결핍·이상이면 물질대사 이상 증상'],
 ['h','03 효소의 작용에 영향을 미치는 요인'],
 ['tbl',['요인','내용'],[['온도','일정 온도까지 반응 속도 증가 → ==최적온도==에서 최대 → 그 이상에서 급격히 감소(==단백질 입체 구조 변형==). 사람 효소 ==35~40 ℃==, 온천 세균 효소 ==70 ℃ 이상=='],['pH','==최적 pH==에서 반응 속도 최대. 위에서 작용하는 ==펩신 pH 2==, 작은창자의 ==트립신 pH 8==. 효소마다 다르며 작용 장소와 관련'],['기질 농도','효소 농도가 일정할 때 처음엔 기질 농도에 ==비례==하여 증가 → 모든 효소가 기질과 결합하면 ==속도 일정(포화)==. 속도를 더 높이려면 ==효소 양을 늘려야 함==']]],
 ['vs',['경쟁적 억제제','==활성부위에 결합==하여 기질과 경쟁\n==기질 농도를 높이면 억제 효과 감소=='],['비경쟁적 억제제','==활성부위가 아닌 다른 부위==에 결합 → 활성부위 구조 변형 → 기질이 결합할 수 없음\n기질 농도를 높여도 억제 효과 유지']],
 ['p','효소억제제 이용: ==아스피린==(염증·발열·통증 물질을 합성하는 효소 억제 → 소염·해열·진통), ==페니실린==(세균 세포벽 형성 효소 억제 → 항생)'],
 ['h','탐구: 카탈레이스 활성에 영향을 미치는 요인'],
 ['p','카탈레이스: ==과산화 수소(H₂O₂)를 물과 산소(O₂)로 분해==하는 효소 (2H₂O₂ → 2H₂O + O₂), 간·감자 등에 들어 있음\n감자즙 묻힌 거름종이를 과산화 수소수에 넣으면 ==산소 기포==로 떠오름\n==조작변인==(온도, pH), ==통제변인==(그 외 모든 조건), ==종속변인==(기포 발생량·거름종이가 떠오르는 시간)\n신뢰도를 높이기 위해 ==3~5회 반복==하여 평균'],
 ['h','04 생활 속 효소의 이용'],
 ['p','발효식품(포도주, 치즈), 청바지 가공, ==혈당 측정 검사지==(포도당산화효소가 포도당을 산화), 식혜 등 식품·화학 공업에 이용'],
 ['flow',['1896 ==부흐너== 효모즙으로 알코올발효 → 발효는 효모 안 ==효소의 작용==, 효소는 생명체 밖에서도 작용','1926 ==섬너== 작두콩에서 유레이스를 결정으로 만들어 ==효소가 단백질==임을 최초로 입증','1930 ==노스럽== 펩신·트립신 결정화','1935 ==스탠리== 바이러스 결정화']],
 ['tip','**효소 = 활성화에너지↓, 반응열 불변, 반응 후 재사용, 기질특이성.** 최적온도·최적 pH 그래프(사람 35~40 ℃, 펩신 pH 2, 트립신 pH 8), **기질 농도↑ → 포화, 경쟁적 억제제는 기질 농도↑로 극복.** 효소 종류별 반응 키워드: 가수분해 = 물, 연결 = ATP, 산화환원 = H·전자.']]};
CPQ['1-1']=[
 {t:'sh',g:A,q:'화학 반응을 일으키는 데 필요한 최소한의 에너지를 [빈칸]에너지라고 한다.',a:['활성화'],m:'활성화',e:'효소는 활성화에너지를 낮추어 반응을 빠르게 일어나게 해요.'},
 {t:'ox',g:A,q:'효소가 있으면 반응물과 생성물의 에너지 차이인 반응열이 달라진다.',a:false,e:'효소는 활성화에너지만 낮추고 반응열은 변하지 않아요.'},
 {t:'mc',g:A,q:'효소와 결합하는 반응물을 무엇이라고 하는가?',o:['생성물','기질','보조인자','억제제','주효소'],a:1,e:'효소와 결합하는 반응물은 기질이고, 기질이 결합하는 효소의 특정 부위가 활성부위예요.'},
 {t:'sh',g:A,q:'효소가 활성부위의 구조에 들어맞는 특정 기질에만 작용하는 특성을 [빈칸]이라고 한다.',a:['기질특이성'],m:'기질특이성',e:'수크레이스가 설탕만 분해하고 엿당에는 작용하지 않는 것이 예예요.'},
 {t:'ox',g:A,q:'효소는 반응이 끝나면 분해되어 없어지므로 한 번만 사용된다.',a:false,e:'효소는 생성물과 분리된 뒤 새로운 기질과 다시 결합하여 반복적으로 사용돼요.'},
 {t:'mc',g:B,q:'효소에서 단백질 부분을 무엇이라고 하는가?',o:['주효소','보조인자','조효소','전효소','기질'],a:0,e:'주효소 + 보조인자 = 전효소예요.'},
 {t:'mc',g:B,q:'물 분자를 첨가하여 기질을 분해하는 반응을 촉매하는 효소는?',o:['산화환원효소','전이효소','가수분해효소','이성질화효소','연결효소'],a:2,e:'가수분해효소는 물 분자를 첨가하여 기질을 분해해요.'},
 {t:'mc',g:C,q:'효소의 활성이 가장 높아 반응 속도가 최대가 되는 온도를 무엇이라고 하는가?',o:['임계온도','최적온도','활성화온도','기초온도','변성온도'],a:1,e:'최적온도는 효소에 따라 다르며 생물의 체온·서식 환경과 관련이 있어요.'},
 {t:'sh',g:C,q:'기질의 농도가 높아져 효소의 반응 속도가 일정해지는 까닭은 모든 [빈칸]가 기질과 결합했기 때문이다.',a:['효소'],m:'효소',e:'이때 반응 속도를 더 높이려면 효소의 양을 늘려야 해요.'},
 {t:'ox',g:D,q:'경쟁적 억제제는 효소의 활성부위에 결합한다.',a:true,e:'비경쟁적 억제제는 활성부위가 아닌 다른 부위에 결합해 활성부위 구조를 변형시켜요.'},
 {lv:'x',t:'mc',g:A,q:'그림은 효소가 있을 때와 없을 때의 반응 경로를 나타낸 것이다. 효소가 있을 때의 반응 경로는 (가)와 (나) 중 하나이다.\n\n[그림]\n\n이에 대한 설명으로 옳은 것은?',fig:{l:CHV([[0,3],[2,3],[4,8],[6,2],[9,2]],'(가)').concat(CHV([[0,3],[2,3],[4,5.5],[6,2],[9,2]],'(나)',0,'#c0392b')),pt:[],ax:1,x:'반응 진행',y:'에너지',yt:[[3,'반응물'],[2,'생성물']]},o:['효소가 있을 때의 경로는 (가)이다.','(나)에서 활성화에너지는 (가)보다 작다.','(가)와 (나)는 반응열이 서로 다르다.','(나)는 효소가 없을 때의 경로이다.','(가)에서는 반응이 일어나지 않는다.'],a:1,e:'효소는 활성화에너지를 낮추므로 봉우리가 낮은 (나)가 효소가 있을 때의 경로예요. 반응물과 생성물의 에너지가 같으므로 반응열은 같아요.'},
 {lv:'x',t:'mc',g:A,q:'효소의 작용 과정 (가)~(다)를 순서대로 옳게 나열한 것은?\n\n(가) 효소가 생성물과 분리된다.\n(나) 기질이 효소의 활성부위에 결합하여 효소기질복합체가 형성된다.\n(다) 기질이 변화하여 생성물이 만들어진다.',o:['(나) → (다) → (가)','(가) → (나) → (다)','(다) → (나) → (가)','(나) → (가) → (다)','(가) → (다) → (나)'],a:0,e:'기질 결합 → 생성물 생성 → 효소와 생성물 분리 순서이고, 분리된 효소는 다시 새로운 기질과 결합해요.'},
 {lv:'x',t:'mc',g:B,q:'효소의 구성에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. 주효소는 단백질 부분이다.\nㄴ. 조효소는 보조인자의 한 종류이다.\nㄷ. 조효소는 주효소보다 열에 약하다.',o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:1,e:'조효소는 주효소에 비해 분자가 작고 열에 강해요.'},
 {lv:'x',t:'mc',g:B,q:'표는 효소 (가)~(다)가 촉매하는 반응의 유형이다. (가)~(다)는 가수분해효소, 연결효소, 산화환원효소 중 하나이다.\n\n[표]\n\n(가)~(다)를 옳게 짝지은 것은?',tb:{h:['효소','촉매하는 반응'],r:[['(가)','물 분자를 첨가하여 기질을 분해한다.'],['(나)','ATP 에너지를 사용하여 두 기질을 연결한다.'],['(다)','H, O 또는 전자를 다른 분자에 전달한다.']]},o:['가수분해효소, 연결효소, 산화환원효소','연결효소, 가수분해효소, 산화환원효소','산화환원효소, 연결효소, 가수분해효소','가수분해효소, 산화환원효소, 연결효소','연결효소, 산화환원효소, 가수분해효소'],a:0,e:'물을 첨가하면 가수분해, ATP를 쓰면 연결, H·전자를 전달하면 산화환원이에요.'},
 {lv:'x',t:'mc',g:C,q:'그래프는 효소 A와 B의 반응 속도를 온도에 따라 나타낸 것이다.\n\n[그림]\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. A의 최적온도는 약 40 ℃이다.\nㄴ. B는 온천에 사는 세균의 효소일 수 있다.\nㄷ. 60 ℃에서 A는 B보다 반응 속도가 빠르다.',fig:{l:CHV([[0,0],[1,1.5],[2,3.5],[4,9],[5,5],[6,1],[7,0]],'A').concat(CHV([[0,0],[2,0.5],[4,2],[6,5.5],[7.5,9],[9,2.5],[10,0]],'B',0,'#c0392b')),pt:[],x:'온도(℃)',y:'반응 속도',xt:[[2,'20'],[4,'40'],[6,'60'],[8,'80']]},o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:1,e:'60 ℃에서는 A의 반응 속도가 거의 0이고 B가 더 빨라요.'},
 {lv:'x',t:'mc',g:C,q:'그래프는 효소 X와 Y의 반응 속도를 pH에 따라 나타낸 것이다. X와 Y는 위에서 작용하는 펩신과 작은창자에서 작용하는 트립신 중 하나이다.\n\n[그림]\n\n이에 대한 설명으로 옳은 것은?',fig:{l:CHV([[1,0],[2,9],[4,2],[5,0]],'X').concat(CHV([[4,0],[6,3],[8,9],[10,1]],'Y',0,'#c0392b')),pt:[],x:'pH',y:'반응 속도',xt:[[2,'2'],[4,'4'],[6,'6'],[8,'8'],[10,'10']]},o:['X는 트립신이다.','Y는 위에서 작용한다.','X의 최적 pH는 약 2이다.','Y의 최적 pH는 약 2이다.','X와 Y의 최적 pH는 같다.'],a:2,e:'X는 펩신(최적 pH 2), Y는 트립신(최적 pH 8)이에요.'},
 {lv:'x',t:'mc',g:C,q:'효소의 농도가 일정할 때 기질의 농도에 따른 반응 속도를 나타낸 그래프이다.\n\n[그림]\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. 구간 Ⅰ에서 기질의 농도가 높아질수록 효소기질복합체가 많이 형성된다.\nㄴ. 구간 Ⅱ에서는 모든 효소가 기질과 결합하고 있다.\nㄷ. 구간 Ⅱ에서 기질의 농도를 더 높이면 반응 속도가 계속 증가한다.',fig:{l:CHV([[0,0],[2,4],[4,7],[6,8.6],[8,9],[10,9]],''),pt:[],x:'기질 농도',y:'반응 속도',tx:[[1.5,9.5,'Ⅰ'],[8,10,'Ⅱ']]},o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:1,e:'구간 Ⅱ는 포화 상태라 기질 농도를 높여도 속도가 늘지 않고, 효소의 양을 늘려야 해요.'},
 {lv:'x',t:'mc',g:D,q:'효소억제제 (가)와 (나)의 특징이다.\n\n(가) 효소의 활성부위에 결합하여 기질의 결합을 방해한다.\n(나) 활성부위가 아닌 다른 부위에 결합하여 활성부위의 구조를 변형시킨다.\n\n(가)와 (나)에 대한 설명으로 옳은 것은?',o:['(가)는 비경쟁적 억제제이다.','(나)는 경쟁적 억제제이다.','(가)의 억제 효과는 기질 농도가 높아지면 감소한다.','(나)의 억제 효과는 기질 농도가 높아지면 감소한다.','(가)와 (나)는 모두 활성부위에 결합한다.'],a:2,e:'(가)는 경쟁적 억제제, (나)는 비경쟁적 억제제예요. 경쟁적 억제제는 기질 농도가 높아지면 기질과의 경쟁에서 밀려 효과가 줄어요.'},
 {lv:'x',t:'mc',g:D,q:'카탈레이스에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. 과산화 수소를 물과 산소로 분해하는 반응을 촉진한다.\nㄴ. 감자즙에 들어 있다.\nㄷ. 이 실험에서 산소 기포가 많이 발생할수록 효소 활성이 높다.',o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:4,e:'감자즙의 카탈레이스가 H₂O₂를 H₂O와 O₂로 분해하고, 산소 기포 발생량으로 활성을 비교해요.'},
 {lv:'x',t:'mc',g:D,q:'다음은 효소의 정체를 밝힌 과학자와 그 업적이다.\n\n(가) 효모즙에서도 알코올발효가 일어남을 발견하여 발효가 효소의 작용임을 밝혔다.\n(나) 작두콩에서 유레이스를 결정으로 만들어 효소가 단백질임을 처음으로 입증하였다.\n\n(가)와 (나)를 옳게 짝지은 것은?',o:['부흐너, 섬너','섬너, 부흐너','부흐너, 노스럽','노스럽, 스탠리','스탠리, 섬너'],a:0,e:'1896년 부흐너, 1926년 섬너의 업적이에요.'}
];
CPMK['1-1']=[
 {g:A,q:'다음은 효소에 대한 학생들의 대화이다.\n\n갑: 효소는 활성화에너지를 낮추어 반응을 촉진해.\n을: 효소가 작용하면 반응물과 생성물의 에너지 차이가 작아져.\n병: 효소는 활성부위와 구조가 맞는 기질에만 작용해.\n\n옳게 말한 학생만을 고른 것은?',o:['갑','병','갑, 병','을, 병','갑, 을, 병'],a:2,e:'효소는 활성화에너지만 낮추고 반응열은 변하지 않아요.'},
 {g:A,q:'효소 E가 기질 S에 작용하여 생성물 P를 만드는 과정에 대한 설명으로 옳은 것은?',o:['E는 반응이 끝나면 분해된다.','S가 E와 결합하여 효소기질복합체가 형성된다.','E는 모든 종류의 S에 작용한다.','P가 생성되는 데 필요한 활성화에너지는 E가 없을 때 더 작다.','E는 P와 영구적으로 결합한다.'],a:1,e:'효소는 기질과 결합하여 복합체를 형성한 뒤 생성물이 만들어지면 분리돼 재사용돼요.'},
 {g:A,q:'수크레이스가 설탕에만 작용하고 엿당에는 작용하지 않는 까닭으로 가장 적절한 것은?',o:['수크레이스는 열에 약하기 때문','활성부위의 구조에 설탕은 들어맞고 엿당은 들어맞지 않기 때문','엿당은 설탕보다 분자가 크기 때문','수크레이스는 보조인자가 없기 때문','엿당은 에너지가 높기 때문'],a:1,e:'기질특이성은 활성부위의 구조와 기질의 구조가 들어맞는지에 따라 결정돼요.'},
 {g:B,q:'표는 효소의 구성 요소 (가)~(다)의 특징이다.\n\n[표]\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. (가)는 주효소이다.\nㄴ. (나)에는 금속 이온이 포함된다.\nㄷ. (다)는 (가)와 (나)가 결합한 것이다.',tb:{h:['구성 요소','특징'],r:[['(가)','효소에서 단백질로 이루어진 부분'],['(나)','비단백질 부분으로 효소의 활성에 필요함'],['(다)','완전한 기능을 나타내는 효소']]},o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:4,e:'(가) 주효소, (나) 보조인자, (다) 전효소예요.'},
 {g:B,q:'조효소에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. NAD⁺와 FAD는 조효소이다.\nㄴ. 조효소는 주효소보다 분자가 작다.\nㄷ. 조효소 하나는 한 가지 주효소의 작용에만 관여한다.',o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:1,e:'조효소 하나가 여러 가지 주효소의 작용에 관여할 수 있어요.'},
 {g:B,q:'효소의 종류와 촉매하는 반응이 옳게 짝지어진 것은?',o:['연결효소 – 물을 첨가하여 기질을 분해한다.','가수분해효소 – ATP 에너지를 이용해 두 기질을 연결한다.','이성질화효소 – 기질의 원자 배열을 바꾼다.','산화환원효소 – 작용기를 제거하여 이중결합을 만든다.','전이효소 – H, O 또는 전자를 다른 분자에 전달한다.'],a:2,e:'가수분해효소는 물을 첨가, 연결효소는 ATP 사용, 산화환원효소는 H·전자 전달, 전이효소는 작용기 전달이에요.'},
 {g:C,q:'표는 효소 X의 반응 속도를 온도에 따라 측정한 결과이다.\n\n[표]\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. X의 최적온도는 40 ℃ 근처이다.\nㄴ. 60 ℃에서 반응 속도가 감소한 것은 입체 구조가 변했기 때문이다.\nㄷ. X는 사람 몸의 효소일 가능성이 높다.',tb:{h:['온도(℃)','20','30','40','50','60'],r:[['상대적 반응 속도','30','70','100','40','5']]},o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:4,e:'사람 몸의 효소의 최적온도는 35~40 ℃이고, 높은 온도에서는 단백질의 입체 구조가 변형돼요.'},
 {g:C,q:'표는 효소 (가)~(다)의 최적 pH이다. (가)~(다)는 펩신, 트립신, 아밀레이스 중 하나이다.\n\n[표]\n\n이에 대한 설명으로 옳은 것은?',tb:{h:['효소','최적 pH','작용 장소'],r:[['(가)','2','위'],['(나)','8','작은창자'],['(다)','7','입']]},o:['(가)는 트립신이다.','(나)는 펩신이다.','(가)는 펩신이다.','(다)는 펩신이다.','(가)와 (나)의 최적 pH는 같다.'],a:2,e:'위에서 pH 2에서 작용하는 (가)가 펩신, 작은창자에서 pH 8에서 작용하는 (나)가 트립신이에요.'},
 {g:C,q:'효소의 농도는 일정하고 기질의 농도를 높이면서 반응 속도를 측정하였더니 기질 농도 40 mM 이상에서 반응 속도가 일정해졌다. 이 상태에서 반응 속도를 더 높일 수 있는 방법은?',o:['기질의 농도를 더 높인다.','효소의 양을 늘린다.','경쟁적 억제제를 넣는다.','pH를 최적 pH에서 멀어지게 한다.','온도를 최적온도보다 크게 높인다.'],a:1,e:'모든 효소가 기질과 결합한 포화 상태에서는 효소의 양을 늘려야 반응 속도가 증가해요.'},
 {g:D,q:'표는 효소 반응에서 억제제 X와 Y를 각각 넣었을 때와 넣지 않았을 때의 기질 농도에 따른 반응 속도(상대값)이다. X는 경쟁적 억제제, Y는 비경쟁적 억제제이다.\n\n[표]\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. 기질 농도가 매우 높을 때 X를 넣은 경우의 최대 속도는 억제제가 없을 때와 같아진다.\nㄴ. Y는 활성부위에 결합한다.\nㄷ. 기질 농도가 매우 높아도 Y를 넣으면 억제제가 없을 때의 최대 속도에 도달하지 못한다.',tb:{h:['기질 농도','1','2','4','8','16'],r:[['억제제 없음','5','8','9.5','10','10'],['X 첨가','2','4','7','9','10'],['Y 첨가','3','4.5','5','5','5']]},o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:2,e:'비경쟁적 억제제 Y는 활성부위가 아닌 다른 부위에 결합하며 기질 농도를 높여도 효과가 유지돼요.'},
 {g:D,q:'다음은 감자즙에 들어 있는 효소의 활성에 영향을 미치는 요인을 알아보기 위한 실험이다.\n\n[실험]\n• 과산화 수소수에 감자즙을 묻힌 거름종이를 넣고, 온도를 달리한 세 비커 (가)~(다)에서 거름종이가 떠오르는 시간을 측정한다.\n• 비커 (가)~(다)의 과산화 수소수의 농도, 양, 거름종이의 크기는 같게 한다.\n\n이 실험에서 조작변인과 종속변인을 옳게 짝지은 것은?',o:['온도, 거름종이가 떠오르는 시간','과산화 수소수의 농도, 온도','거름종이의 크기, 온도','거름종이가 떠오르는 시간, 온도','과산화 수소수의 양, 거름종이가 떠오르는 시간'],a:0,e:'조작변인은 의도적으로 바꾸는 온도이고, 종속변인은 그에 따라 변하는 거름종이가 떠오르는 시간이에요.'},
 {g:D,q:'효소의 이용에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. 아스피린은 염증과 통증을 일으키는 물질을 합성하는 효소의 작용을 억제한다.\nㄴ. 페니실린은 세균의 세포벽 형성에 관여하는 효소의 작용을 억제한다.\nㄷ. 혈당 측정 검사지에는 포도당을 산화하는 효소가 이용된다.',o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:4,e:'아스피린과 페니실린은 효소억제제이고, 혈당 측정 검사지에는 포도당산화효소가 쓰여요.'},
 {g:D,q:'효소의 정체를 밝힌 과정에 대한 설명으로 옳지 않은 것은?',o:['부흐너는 효모즙에서도 알코올발효가 일어남을 발견하였다.','부흐너의 발견으로 효소가 생명체 밖에서도 작용할 수 있음이 알려졌다.','섬너는 유레이스를 결정으로 만들어 효소가 단백질임을 처음 입증하였다.','노스럽은 펩신과 트립신을 결정으로 만들었다.','효소는 살아 있는 효모 세포 안에서만 작용한다는 것이 입증되었다.'],a:4,e:'부흐너의 실험으로 효소가 살아 있는 세포 밖에서도 작용함이 밝혀졌어요.'}
];
Object.assign(TIPS,{[A]:'효소는 활성화에너지를 낮출 뿐 반응열은 불변, 반응 후 재사용, 기질특이성(활성부위 구조에 맞는 기질만 결합). 과정: 기질 결합 → 효소기질복합체 → 생성물 → 효소 분리!',[B]:'주효소(단백질) + 보조인자(금속 이온·조효소) = 전효소. 종류: 가수분해(물 첨가), 연결(ATP 사용), 산화환원(H·전자), 전이(작용기 전달), 이성질화(배열 변화), 제거(이중결합)!',[C]:'최적온도(사람 35~40 ℃, 온천 세균 70 ℃ 이상), 최적 pH(펩신 2, 트립신 8). 고온·극단적 pH → 입체 구조 변형 → 활성 감소. 기질 농도↑ → 포화, 이때는 효소 양을 늘려야 해요!',[D]:'경쟁적 억제제 = 활성부위 결합, 기질 농도↑로 극복 / 비경쟁적 = 다른 부위 결합(구조 변형), 극복 불가. 카탈레이스: H₂O₂ → H₂O + O₂. 부흐너(1896) → 섬너(1926)!'});
})();
// ===== Ⅲ. 세포호흡과 광합성 =====
// ----- 01 세포호흡 (교과서 87~95쪽) -----
(()=>{const A='마이토콘드리아와 세포호흡의 단계',B='해당 과정과 TCA 회로',C='산화적 인산화',D='ATP 생성량과 에너지효율';
NOTE[CPN]['2-0']={pg:CPPG(3,1,87,95),b:[
 ['h','01 마이토콘드리아의 구조와 기능'],
 ['p','==외막과 내막의 이중막==, 외막과 내막 사이 ==막사이공간==\n내막이 안쪽으로 접힌 ==크리스타==(표면적 증가 → 세포호흡 효율↑), 내막 안쪽 공간 ==바탕질==\n==내막과 바탕질==에 세포호흡 효소 / ==내막==에 ==전자전달계와 ATP 합성효소=='],
 ['h','02 세포호흡 과정'],
 ['key','세포호흡 반응식','C₆H₁₂O₆ + 6O₂ + 6H₂O → ==6CO₂ + 12H₂O + 에너지==\n포도당은 CO₂로 ==산화==, 산소는 물로 ==환원==, 포도당의 에너지는 ==ATP의 화학 에너지와 열==로 전환'],
 ['tbl',['단계','장소','핵심 내용','ATP 생성 방식'],[
  ['① 해당 과정','==세포질==','포도당 1분자 → ==피루브산 2분자==, ATP 2분자 소모·4분자 생성(==순생성 2ATP==), ==NADH 2분자==, ==CO₂ 방출 없음==, 산소 직접 사용 X','==기질수준인산화=='],
  ['② 피루브산의 산화 + TCA 회로','==마이토콘드리아 바탕질==','피루브산 → 아세틸조효소 A(CO₂ 방출, NADH) → TCA 회로에서 ==CO₂==로 분해, ==NADH·FADH₂== 생성','==기질수준인산화=='],
  ['③ 산화적 인산화','==마이토콘드리아 내막==','NADH·FADH₂의 전자가 ==전자전달계==를 거쳐 ==산소(최종 전자수용체)==와 결합하여 물 생성, ==H⁺ 농도 기울기 → ATP 합성효소==로 ATP 합성','==산화적 인산화== (화학삼투) / ATP 대부분 생성']]],
 ['p','ATP 합성 방식 3가지: ==기질수준인산화, 산화적 인산화, 광인산화==(광합성)'],
 ['h','해당 과정'],
 ['p','포도당(C₆) 1분자 → 피루브산(C₃) 2분자, 탄소가 모두 피루브산에 남음 → ==CO₂ 방출 없음==\n==탈수소효소==의 작용으로 ==NAD⁺가 H⁺과 e⁻을 받아 NADH==로 환원 (NAD⁺ = 전자운반체, 탈수소효소의 조효소)\n해당 과정 후에도 포도당의 에너지 대부분은 ==피루브산에 남아 있음==\n==기질수준인산화==: 효소 작용으로 ==기질에 결합한 인산기가 ADP로 전달==되어 ATP 생성'],
 ['h','피루브산의 산화와 TCA 회로'],
 ['flow',['피루브산(C₃)이 산소가 있을 때 ==바탕질==로 이동','피루브산 → ==아세틸조효소 A(C₂)== + ==CO₂== 1분자 + NADH','아세틸조효소 A + 옥살아세트산(C₄) → ==시트르산(C₆)== → … → 옥살아세트산 (순환)','TCA 1회전: ==CO₂ 2분자, ATP 1, NADH 3, FADH₂ 1==']],
 ['key','마이토콘드리아에서 피루브산 1분자가 분해될 때','==CO₂ 3분자==, ==ATP 1분자==, ==NADH 4분자==, ==FADH₂ 1분자==\n→ 포도당 1분자(피루브산 2분자)로는 ==CO₂ 6분자, ATP 2, NADH 8, FADH₂ 2== (해당 과정의 NADH 2 포함 시 NADH 10)'],
 ['h','산화적 인산화'],
 ['ul',['전자전달계: 내막의 여러 전자운반체 — 전자 친화력이 ==낮은 것 → 높은 것==, 전자가 이동하며 에너지를 조금씩 방출','일부 전자운반체가 방출된 에너지로 ==H⁺을 바탕질 → 막사이공간으로 능동수송== → 내막 경계로 ==H⁺ 농도 기울기==(막사이공간 > 바탕질)','H⁺이 ==ATP 합성효소==를 통해 바탕질 쪽으로 ==확산==하면서 ATP 합성 = ==화학삼투==','==산소가 없으면 전자의 흐름이 정지==되어 ATP가 합성되지 못함','NADH 1분자 → ATP ==약 2.5분자==, FADH₂ 1분자 → ATP ==약 1.5분자==']],
 ['p','실험: pH 9로 만든 마이토콘드리아를 pH 7 수용액에 옮기면 H⁺이 바탕질로 확산하며 ATP 합성 → ==ATP 합성의 원동력 = H⁺의 농도 기울기=='],
 ['h','03 세포호흡의 에너지효율'],
 ['tbl',['구분','ATP 수'],[['기질수준인산화 (해당 과정 2 + TCA 회로 2)','==4 ATP=='],['산화적 인산화 (NADH 10 × 2.5 + FADH₂ 2 × 1.5)','최대 ==28 ATP=='],['합계','최대 ==32 ATP==']]],
 ['p','포도당 1분자로 해당 과정 + 피루브산의 산화 + TCA 회로 동안 ==NADH 10분자, FADH₂ 2분자== 생성\nATP를 가장 많이 만드는 단계 = ==산화적 인산화==\n에너지효율(%) = (32 × 7.3 kcal/mol ÷ 686 kcal/mol) × 100 ≈ ==34 %== (포도당 1몰 완전 연소 686 kcal, ATP 1몰 약 7.3 kcal 저장) → 나머지 ==약 66 %는 열==로 방출(체온 유지 등)\n세포호흡에는 주로 ==탄수화물==, 단백질·지방도 해당 과정·TCA 회로의 중간 산물로 전환되어 이용'],
 ['tip','**CO₂는 해당 과정에서는 안 나오고, 피루브산 산화·TCA 회로(마이토콘드리아 바탕질)에서 나옴.** 포도당 1분자: **해당 NADH 2 + 피루브산 산화·TCA 8 = 10 NADH, FADH₂ 2, 기질수준 4 ATP, 산화적 인산화 28 ATP, 총 32 ATP.** 산소 = **최종 전자수용체 → 물 생성.** ATP 최다 생성 = **산화적 인산화(내막).**']]};
CPQ['2-0']=[
 {t:'sh',g:A,q:'마이토콘드리아의 내막이 안쪽으로 접혀 들어간 주름진 구조를 [빈칸]라고 한다.',a:['크리스타'],m:'크리스타',e:'크리스타 덕분에 내막의 표면적이 넓어져 세포호흡이 효율적으로 일어나요.'},
 {t:'mc',g:A,q:'세포호흡의 첫 번째 단계인 해당 과정이 일어나는 장소는?',o:['세포질','마이토콘드리아 바탕질','마이토콘드리아 내막','엽록체 스트로마','핵'],a:0,e:'해당 과정은 세포질에서 일어나고, 나머지 두 단계는 마이토콘드리아에서 일어나요.'},
 {t:'ox',g:A,q:'세포호흡의 반응식에서 포도당은 이산화 탄소로 산화되고, 산소는 물로 환원된다.',a:true,e:'세포호흡은 전자를 주고받는 산화환원반응이에요.'},
 {t:'sh',g:B,q:'해당 과정에서 포도당 1분자는 [빈칸]분자의 피루브산으로 분해된다.',a:['2','두','이'],m:'2',e:'이 과정에서 ATP 2분자(순생성)와 NADH 2분자가 생성돼요.'},
 {t:'ox',g:B,q:'해당 과정에서는 이산화 탄소가 방출된다.',a:false,e:'포도당(C₆)의 탄소가 모두 피루브산(C₃) 2분자로 전환되어 이산화 탄소가 방출되지 않아요.'},
 {t:'mc',g:B,q:'효소의 작용으로 기질에 결합하고 있던 인산기가 ADP로 전달되어 ATP가 합성되는 방식은?',o:['산화적 인산화','광인산화','기질수준인산화','화학삼투','능동수송'],a:2,e:'해당 과정과 TCA 회로에서는 기질수준인산화로 ATP가 합성돼요.'},
 {t:'mc',g:C,q:'마이토콘드리아에서 전자전달계의 최종 전자수용체는?',o:['물','이산화 탄소','산소','NAD⁺','포도당'],a:2,e:'전자는 최종적으로 산소와 결합하여 물을 합성해요.'},
 {t:'sh',g:C,q:'H⁺이 ATP 합성효소를 통해 확산하면서 ATP가 합성되는 원리를 [빈칸]이라고 한다.',a:['화학삼투'],m:'화학삼투',e:'내막 경계에 형성된 H⁺의 농도 기울기가 ATP 합성의 원동력이에요.'},
 {t:'mc',g:D,q:'포도당 1분자가 세포호흡으로 분해될 때 생성되는 ATP의 최대 개수는?',o:['2','4','28','30','32'],a:4,e:'기질수준인산화로 4ATP, 산화적 인산화로 최대 28ATP, 합 최대 32ATP가 생성돼요.'},
 {t:'ox',g:D,q:'세포호흡에서 포도당에 저장된 에너지의 대부분(약 66 %)은 열로 방출된다.',a:true,e:'ATP에 저장되는 에너지는 약 34 %이고 나머지는 열로 방출돼 체온 유지 등에 쓰여요.'},
 {lv:'x',t:'mc',g:A,q:'표는 세포호흡의 세 단계 (가)~(다)를 나타낸 것이다.\n\n[표]\n\n(가)~(다)를 옳게 짝지은 것은?',tb:{h:['단계','장소','특징'],r:[['(가)','세포질','포도당이 피루브산으로 분해됨'],['(나)','마이토콘드리아 바탕질','피루브산이 CO₂로 분해됨'],['(다)','마이토콘드리아 내막','H⁺ 농도 기울기를 이용해 ATP가 합성됨']]},o:['해당 과정, 산화적 인산화, TCA 회로','해당 과정, 피루브산의 산화 및 TCA 회로, 산화적 인산화','피루브산의 산화 및 TCA 회로, 해당 과정, 산화적 인산화','산화적 인산화, 해당 과정, TCA 회로','해당 과정, 산화적 인산화, 피루브산의 산화 및 TCA 회로'],a:1,e:'장소와 특징으로 (가) 해당 과정, (나) 피루브산의 산화 및 TCA 회로, (다) 산화적 인산화를 구분해요.'},
 {lv:'x',t:'mc',g:A,q:'마이토콘드리아의 구조와 기능에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. 이중막으로 둘러싸여 있다.\nㄴ. 내막에 전자전달계와 ATP 합성효소가 있다.\nㄷ. 크리스타가 발달해 내막의 표면적이 넓다.',o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:4,e:'세 설명 모두 옳아요.'},
 {lv:'x',t:'mc',g:B,q:'다음은 세포호흡의 한 단계에서 일어나는 반응이다.\n\n포도당(C₆) 1분자 → 피루브산(C₃) 2분자 + ATP 2분자(순생성) + NADH 2분자\n\n이에 대한 설명으로 옳은 것은?',o:['마이토콘드리아에서 일어난다.','산소가 직접 사용된다.','이산화 탄소가 방출된다.','탈수소효소의 작용으로 NAD⁺가 NADH로 환원된다.','산화적 인산화로 ATP가 합성된다.'],a:3,e:'해당 과정은 세포질에서 일어나며 산소를 직접 쓰지 않고 CO₂를 방출하지 않아요. ATP는 기질수준인산화로 합성돼요.'},
 {lv:'x',t:'mc',g:B,q:'피루브산 1분자가 마이토콘드리아 바탕질에서 완전히 분해될 때 생성되는 CO₂, NADH, FADH₂, ATP의 분자 수를 옳게 짝지은 것은?',o:['CO₂ 2, NADH 3, FADH₂ 1, ATP 1','CO₂ 3, NADH 4, FADH₂ 1, ATP 1','CO₂ 3, NADH 3, FADH₂ 2, ATP 2','CO₂ 6, NADH 8, FADH₂ 2, ATP 2','CO₂ 1, NADH 1, FADH₂ 1, ATP 1'],a:1,e:'피루브산의 산화에서 CO₂ 1·NADH 1, TCA 회로에서 CO₂ 2·ATP 1·NADH 3·FADH₂ 1이므로 합하면 CO₂ 3, NADH 4, FADH₂ 1, ATP 1이에요.'},
 {lv:'x',t:'mc',g:B,q:'포도당 1분자가 세포호흡으로 완전히 분해될 때, 마이토콘드리아에서 방출되는 이산화 탄소 분자 수는? (단, 포도당의 탄소는 모두 CO₂로 방출된다.)',o:['2','3','4','6','12'],a:3,e:'포도당(C₆)의 탄소 6개는 해당 과정에서는 피루브산에 남고, 마이토콘드리아에서 CO₂ 6분자로 방출돼요.'},
 {lv:'x',t:'mc',g:C,q:'마이토콘드리아에서 산화적 인산화가 일어날 때의 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. 전자전달계를 거치는 전자의 에너지로 H⁺이 막사이공간으로 이동한다.\nㄴ. H⁺은 ATP 합성효소를 통해 바탕질 쪽으로 확산한다.\nㄷ. 산소가 없어도 전자의 흐름은 계속된다.',o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:1,e:'산소가 없으면 전자의 흐름이 정지되어 ATP가 합성되지 못해요.'},
 {lv:'x',t:'mc',g:C,q:'마이토콘드리아 내막을 경계로 H⁺의 농도가 막사이공간이 바탕질보다 높게 유지될 때에 대한 설명으로 옳은 것은?',o:['H⁺이 바탕질에서 막사이공간으로 확산한다.','H⁺이 막사이공간에서 바탕질로 ATP 합성효소를 통해 이동한다.','ATP 합성효소는 H⁺이 이동하지 않아도 ATP를 합성한다.','전자운반체는 H⁺을 막사이공간에서 바탕질로 이동시킨다.','바탕질의 pH가 막사이공간보다 낮다.'],a:1,e:'H⁺은 농도 기울기에 따라 ATP 합성효소를 통해 막사이공간에서 바탕질로 확산하며 ATP 합성에 이용돼요. 바탕질의 pH가 더 높아요.'},
 {lv:'x',t:'mc',g:D,q:'포도당 1분자가 세포호흡으로 분해되는 동안 NADH 10분자와 FADH₂ 2분자가 산화적 인산화에서 모두 산화될 때 생성되는 ATP의 분자 수는? (단, NADH 1분자당 2.5ATP, FADH₂ 1분자당 1.5ATP이다.)',o:['25','26','28','30','32'],a:2,e:'10 × 2.5 + 2 × 1.5 = 28 ATP예요.'},
 {lv:'x',t:'mc',g:D,q:'표는 포도당 1분자가 세포호흡으로 분해될 때 단계별 ATP 생성량을 나타낸 것이다.\n\n[표]\n\n이에 대한 설명으로 옳은 것은?',tb:{h:['단계','ATP 생성량(분자 수)'],r:[['해당 과정','2'],['피루브산의 산화 및 TCA 회로','2'],['산화적 인산화','28']]},o:['ATP가 가장 많이 생성되는 단계는 해당 과정이다.','기질수준인산화로 생성되는 ATP는 4분자이다.','총 ATP는 30분자이다.','산화적 인산화는 세포질에서 일어난다.','TCA 회로에서만 기질수준인산화가 일어난다.'],a:1,e:'해당 과정 2 + TCA 회로 2 = 4ATP가 기질수준인산화로 생성돼요. 총합은 32, 산화적 인산화는 마이토콘드리아 내막에서 일어나요.'},
 {lv:'x',t:'mc',g:D,q:'포도당 1몰이 완전 연소될 때 방출되는 에너지는 686 kcal이고, ATP 1몰이 합성될 때 저장되는 에너지는 7.3 kcal이다. 세포호흡으로 포도당 1분자가 분해되어 32ATP가 생성될 때의 에너지효율은 약 몇 %인가?',o:['약 17 %','약 24 %','약 34 %','약 66 %','약 90 %'],a:2,e:'(32 × 7.3 ÷ 686) × 100 ≈ 34 %예요.'}
];
CPMK['2-0']=[
 {g:A,q:'표는 세포호흡의 단계 (가)~(다)에서 CO₂ 방출과 ATP 합성 방식을 나타낸 것이다. (가)~(다)는 해당 과정, 피루브산의 산화 및 TCA 회로, 산화적 인산화를 순서 없이 나타낸 것이다.\n\n[표]\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. (가)는 해당 과정이다.\nㄴ. (나)는 마이토콘드리아 바탕질에서 일어난다.\nㄷ. (다)에서 ATP가 가장 많이 생성된다.',tb:{h:['단계','CO₂ 방출','ATP 합성 방식'],r:[['(가)','없음','기질수준인산화'],['(나)','있음','기질수준인산화'],['(다)','없음','산화적 인산화']]},o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:4,e:'CO₂를 방출하지 않고 기질수준인산화가 일어나는 (가)는 해당 과정, (나)는 TCA 회로, (다)는 산화적 인산화예요.'},
 {g:A,q:'다음은 세포호흡에 대한 학생들의 대화이다.\n\n갑: 세포호흡은 포도당과 같은 유기물을 산화·분해하여 에너지를 방출하는 반응이야.\n을: 세포호흡의 모든 단계는 마이토콘드리아에서 일어나.\n병: 방출된 에너지는 ATP의 화학 에너지와 열로 전환돼.\n\n옳게 말한 학생만을 고른 것은?',o:['갑','을','갑, 병','을, 병','갑, 을, 병'],a:2,e:'해당 과정은 세포질에서 일어나요.'},
 {g:B,q:'다음은 포도당 1분자가 해당 과정을 거칠 때의 변화이다.\n\n• 포도당(C₆) 1분자에서 피루브산(C₃) 2분자가 생성된다.\n• ATP 2분자가 소모되고 4분자가 생성된다.\n• NAD⁺가 NADH로 환원된다.\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. 해당 과정에서 순생성되는 ATP는 2분자이다.\nㄴ. 해당 과정에서는 이산화 탄소가 방출된다.\nㄷ. 포도당의 에너지 대부분은 해당 과정 후에도 피루브산에 남아 있다.',o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:2,e:'포도당의 탄소가 모두 피루브산에 남으므로 해당 과정에서는 CO₂가 방출되지 않아요.'},
 {g:B,q:'표는 세포호흡 과정 중 (가)~(다)에서 생성되는 물질의 분자 수(포도당 1분자 기준)이다. (가)~(다)는 해당 과정, 피루브산의 산화, TCA 회로를 순서 없이 나타낸 것이다.\n\n[표]\n\n(가)~(다)를 옳게 짝지은 것은?',tb:{h:['구분','CO₂','NADH','FADH₂','ATP'],r:[['(가)','0','2','0','2'],['(나)','2','2','0','0'],['(다)','4','6','2','2']]},o:['해당 과정, 피루브산의 산화, TCA 회로','피루브산의 산화, 해당 과정, TCA 회로','TCA 회로, 해당 과정, 피루브산의 산화','해당 과정, TCA 회로, 피루브산의 산화','피루브산의 산화, TCA 회로, 해당 과정'],a:0,e:'CO₂가 없고 ATP 2분자를 만드는 (가)는 해당 과정, CO₂ 2·NADH 2인 (나)는 피루브산의 산화, 포도당 1분자당 TCA 회로 2회전인 (다)는 CO₂ 4·NADH 6·FADH₂ 2·ATP 2예요.'},
 {g:B,q:'TCA 회로 1회전에서 아세틸조효소 A 1분자가 분해될 때 생성되는 물질의 분자 수를 옳게 나타낸 것은?',o:['CO₂ 1, ATP 1, NADH 1, FADH₂ 1','CO₂ 2, ATP 1, NADH 3, FADH₂ 1','CO₂ 2, ATP 2, NADH 2, FADH₂ 2','CO₂ 3, ATP 1, NADH 4, FADH₂ 1','CO₂ 6, ATP 2, NADH 6, FADH₂ 2'],a:1,e:'TCA 회로 1회전: CO₂ 2분자, ATP 1분자, NADH 3분자, FADH₂ 1분자가 생성돼요.'},
 {g:C,q:'다음은 마이토콘드리아에서 ATP 합성 원리를 알아보기 위한 실험이다.\n\n[실험]\n• 분리한 마이토콘드리아를 pH 9의 수용액에 넣어 내부(바탕질)를 pH 9로 만든다.\n• 이 마이토콘드리아를 pH 7의 수용액으로 옮기고 ADP와 무기 인산을 공급한다.\n• 마이토콘드리아에서 ATP가 합성되었다.\n\n이 실험에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은? (단, pH는 수소 이온 농도가 높을수록 낮다.)\n\n<보기>\nㄱ. ATP 합성의 원동력은 H⁺의 농도 기울기이다.\nㄴ. H⁺은 ATP 합성효소를 통해 이동한다.\nㄷ. 이 실험은 전자전달계가 없어도 ATP가 합성될 수 있음을 보여 준다.',o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:4,e:'인위적으로 만든 H⁺ 농도 기울기만으로도 ATP가 합성돼요.'},
 {g:C,q:'다음은 마이토콘드리아 내막에서 일어나는 반응이다.\n\n(가) NADH와 FADH₂가 전자전달계에 전자를 전달한다.\n(나) 전자가 전달되면서 H⁺이 바탕질에서 막사이공간으로 이동한다.\n(다) H⁺이 ATP 합성효소를 통해 바탕질로 확산되면서 ATP가 합성된다.\n(라) 전자가 산소와 결합하여 물이 생성된다.\n\n이에 대한 설명으로 옳은 것은?',o:['(나)에서 H⁺은 농도 기울기에 따라 확산한다.','(다)는 기질수준인산화이다.','(라)에서 산소는 최종 전자수용체이다.','(가)에서 NADH는 환원된다.','(라)는 해당 과정에서 일어난다.'],a:2,e:'(나)의 H⁺ 이동은 에너지를 쓰는 능동수송이고, (가)에서 NADH는 산화돼요. (다)는 화학삼투에 의한 산화적 인산화예요.'},
 {g:D,q:'표는 포도당 1분자가 세포호흡으로 완전히 분해될 때, 단계별로 생성되는 NADH와 FADH₂의 분자 수이다.\n\n[표]\n\n산화적 인산화에서 생성되는 ATP의 최대 분자 수는? (단, NADH 1분자당 2.5ATP, FADH₂ 1분자당 1.5ATP이다.)',tb:{h:['단계','NADH','FADH₂'],r:[['해당 과정','2','0'],['피루브산의 산화','2','0'],['TCA 회로','6','2']]},o:['20','24','26','28','32'],a:3,e:'NADH 10 × 2.5 + FADH₂ 2 × 1.5 = 28 ATP예요.'},
 {g:D,q:'다음은 세포호흡의 에너지효율에 대한 설명이다.\n\n• 포도당 1몰이 완전 연소될 때 방출되는 에너지는 686 kcal이다.\n• ATP 1몰이 합성될 때 약 7.3 kcal의 에너지가 저장된다.\n• 세포호흡으로 포도당 1분자에서 32ATP가 생성된다.\n\n이에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. 에너지효율은 약 34 %이다.\nㄴ. 나머지 에너지는 주로 열로 방출된다.\nㄷ. 방출되는 열은 체온 유지에 이용된다.',o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:4,e:'약 66 %가 열로 방출되어 체온 유지 등에 사용돼요.'},
 {g:A,q:'세포호흡의 반응식 C₆H₁₂O₆ + 6O₂ + 6H₂O → 6CO₂ + 12H₂O + 에너지 에 대한 설명으로 옳은 것은?',o:['포도당은 환원된다.','산소는 산화된다.','물은 반응물과 생성물에 모두 나타난다.','이 반응은 광합성의 반응식이다.','반응물의 에너지가 생성물보다 낮다.'],a:2,e:'물은 반응물 6분자, 생성물 12분자로 나타나요. 포도당은 산화되고 산소는 환원되며, 이화작용이라 반응물의 에너지가 더 높아요.'},
 {g:C,q:'다음 중 산소가 없을 때 마이토콘드리아에서 일어나는 변화로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. 전자전달계에서 전자의 흐름이 정지된다.\nㄴ. H⁺ 농도 기울기가 형성되지 못한다.\nㄷ. 산화적 인산화에 의한 ATP 합성이 일어나지 못한다.',o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:4,e:'산소가 최종 전자수용체라서 없으면 전자 흐름이 멈추고, H⁺ 이동과 ATP 합성이 일어나지 못해요.'},
 {g:B,q:'탈수소효소와 NAD⁺에 대한 설명으로 옳은 것만을 <보기>에서 고른 것은?\n\n<보기>\nㄱ. NAD⁺는 탈수소효소의 조효소이다.\nㄴ. NAD⁺는 수소 이온과 전자를 받아 NADH로 환원된다.\nㄷ. NADH는 산화적 인산화에서 전자전달계에 전자를 전달한다.',o:['ㄱ','ㄱ, ㄴ','ㄱ, ㄷ','ㄴ, ㄷ','ㄱ, ㄴ, ㄷ'],a:4,e:'NAD⁺는 전자운반체이면서 탈수소효소의 조효소예요.'},
 {g:D,q:'세포호흡에서 ATP가 생성되는 단계에 대한 설명으로 옳은 것은?',o:['ATP는 해당 과정에서만 생성된다.','ATP는 산화적 인산화에서만 생성된다.','ATP는 세 단계에서 모두 생성되며, 산화적 인산화에서 가장 많이 생성된다.','TCA 회로에서는 ATP가 생성되지 않는다.','해당 과정에서 생성되는 ATP가 가장 많다.'],a:2,e:'ATP는 해당 과정, 피루브산의 산화 및 TCA 회로, 산화적 인산화에서 모두 생성되며 대부분은 산화적 인산화에서 만들어져요.'}
];
Object.assign(TIPS,{[A]:'세포호흡 3단계: 해당 과정(세포질) → 피루브산의 산화·TCA 회로(바탕질) → 산화적 인산화(내막). 산소는 최종 전자수용체(→ 물)!',[B]:'해당 과정: CO₂ X, 순 ATP 2, NADH 2, 기질수준인산화. TCA 1회전: CO₂ 2, ATP 1, NADH 3, FADH₂ 1. 피루브산 1분자 → CO₂ 3, ATP 1, NADH 4, FADH₂ 1!',[C]:'전자전달계 → H⁺을 바탕질에서 막사이공간으로 능동수송 → H⁺ 농도 기울기 → ATP 합성효소를 통한 확산 = 화학삼투. 산소 없으면 전자 흐름 정지!',[D]:'포도당 1분자: 기질수준 4 + 산화적 인산화 28(NADH 10 × 2.5 + FADH₂ 2 × 1.5) = 최대 32 ATP. 에너지효율 = 32 × 7.3 ÷ 686 × 100 ≈ 34 %!'});
})();
